import java.lang.management.ManagementFactory;
import java.lang.management.MemoryMXBean;
import java.lang.management.OperatingSystemMXBean;
import java.lang.management.RuntimeMXBean;
import java.util.HashMap;
import java.util.Map;

public class SystemHealthMonitor {
    public Map<String, Object> getSystemHealth() {
        Map<String, Object> healthMetrics = new HashMap<>();
        healthMetrics.put("status", "HEALTHY");

        // Memory metrics from MemoryMXBean
        MemoryMXBean memoryMXBean = ManagementFactory.getMemoryMXBean();
        healthMetrics.put("heapMemoryUsage", memoryMXBean.getHeapMemoryUsage().getUsed());
        healthMetrics.put("nonHeapMemoryUsage", memoryMXBean.getNonHeapMemoryUsage().getUsed());

        // System metrics from OperatingSystemMXBean
        OperatingSystemMXBean osBean = ManagementFactory.getOperatingSystemMXBean();
        healthMetrics.put("systemLoadAverage", osBean.getSystemLoadAverage());
        healthMetrics.put("availableProcessors", osBean.getAvailableProcessors());

        // Uptime from RuntimeMXBean
        RuntimeMXBean runtimeMXBean = ManagementFactory.getRuntimeMXBean();
        healthMetrics.put("uptime", runtimeMXBean.getUptime());

        // Memory metrics from Runtime
        Runtime runtime = Runtime.getRuntime();
        healthMetrics.put("totalMemory", runtime.totalMemory());
        healthMetrics.put("freeMemory", runtime.freeMemory());

        return healthMetrics;
    }
}

