import java.util.Collections;
import java.util.stream.Collectors;
import java.util.Optional;

class LogAnalyzer {

    public Map<String, Object> analyzeLogs(List<SysLog> logs) {
        if (logs == null || logs.isEmpty()) {
            Map<String, Object> errorMap = new HashMap<>();
            errorMap.put("error", "No logs provided for analysis");
            return errorMap;
        }

        Map<String, Object> result = new HashMap<>();
        result.put("total", logs.size());

        // Calculate user frequency using streams
        Map<String, Long> userFrequency = logs.stream()
            .collect(Collectors.groupingBy(
                SysLog::getUsername,
                Collectors.counting()
            ));

        result.put("userFrequency", userFrequency);

        // Find the most active user
        Optional<Map.Entry<String, Long>> mostActiveEntry = userFrequency.entrySet()
            .stream()
            .max(Map.Entry.comparingByValue());

        mostActiveEntry.ifPresent(entry -> 
            result.put("mostActiveUser", entry.getKey()));

        // Calculate time-based statistics
        long earliestLog = logs.stream()
            .mapToLong(SysLog::getTime)
            .min()
            .orElse(0L);

        long latestLog = logs.stream()
            .mapToLong(SysLog::getTime)
            .max()
            .orElse(0L);

        long timeRange = latestLog - earliestLog;

        result.put("earliestLog", earliestLog);
        result.put("latestLog", latestLog);
        result.put("timeRange", timeRange);

        // Calculate severity distribution
        Map<String, Long> severityDistribution = logs.stream()
            .collect(Collectors.groupingBy(
                SysLog::getSeverity,
                Collectors.counting()
            ));

        result.put("severityDistribution", severityDistribution);

        // Find the longest message
        Optional<String> longestMessage = logs.stream()
            .map(SysLog::getMessage)
            .max((msg1, msg2) -> Integer.compare(msg1.length(), msg2.length()));

        longestMessage.ifPresent(message -> 
            result.put("longestMessage", message));

        return result;
    }

    public static class SysLog {
        private String username;
        private String message;
        private long time;
        private String severity;

        public SysLog(String username, String message, long time, String severity) {
            this.username = username;
            this.message = message;
            this.time = time;
            this.severity = severity;
        }

        public String getUsername() { return username; }
        public String getMessage() { return message; }
        public long getTime() { return time; }
        public String getSeverity() { return severity; }
    }
}
