import java.util.concurrent.ConcurrentHashMap;

public class ThreadResourceManager {
    private ConcurrentHashMap<String, Thread> threadMap;

    public ThreadResourceManager() {
        threadMap = new ConcurrentHashMap<>();
    }

    public boolean createDaemonThread(String threadName, Runnable task) {
        if (threadName == null || task == null) {
            return false;
        }

        Thread newThread = new Thread(task);
        newThread.setName(threadName);
        newThread.setDaemon(true);

        if (threadMap.putIfAbsent(threadName, newThread) != null) {
            return false;
        }

        newThread.start();
        return true;
    }
}

