import java.util.ArrayList;

class BookmarkAnalyzer {

    public BookmarkAnalysisResult analyzeBookmarks(List<String> bookmarks, int minLength) {
        if (bookmarks == null) {
            throw new IllegalArgumentException("Bookmarks list cannot be null");
        }

        BookmarkAnalysisResult result = new BookmarkAnalysisResult();
        result.totalCount = bookmarks.size();

        // Filter valid bookmarks and calculate statistics
        List<String> validBookmarks = new ArrayList<>();
        for (String bookmark : bookmarks) {
            if (bookmark != null && bookmark.length() >= minLength) {
                validBookmarks.add(bookmark);
            }
        }

        result.validCount = validBookmarks.size();
        result.invalidCount = result.totalCount - result.validCount;

        // Calculate average length
        if (result.validCount > 0) {
            double totalLength = 0;
            for (String bookmark : validBookmarks) {
                totalLength += bookmark.length();
            }
            result.averageLength = totalLength / result.validCount;
        } else {
            result.averageLength = 0.0;
        }

        // Initialize remaining fields to default values
        result.longestBookmark = null;
        result.shortestBookmark = null;

        return result;
