import java.util.Arrays;
import java.util.Comparator;

public class Venue {
    private int rows;
    private int columns;
    private boolean[][] seats;
    private int[] columnOrder;

    public Venue(int rows, int columns) {
        this.rows = rows;
        this.columns = columns;
        this.seats = new boolean[rows][columns];
        this.columnOrder = new int[columns];
        precomputeColumnOrder();
    }

    private void precomputeColumnOrder() {
        double center = (columns - 1) / 2.0;
        Integer[] indices = new Integer[columns];
        for (int i = 0; i < columns; i++) {
            indices[i] = i;
        }
        Arrays.sort(indices, new Comparator<Integer>() {
            @Override
            public int compare(Integer a, Integer b) {
                double distA = Math.abs(a - center);
                double distB = Math.abs(b - center);
                if (distA < distB) {
                    return -1;
                } else if (distA > distB) {
                    return 1;
                } else {
                    return a - b;
                }
            }
        });
        for (int i = 0; i < columns; i++) {
            columnOrder[i] = indices[i];
        }
    }

    public int getNumberOfSeats() {
        return rows * columns;
    }

    public boolean reserveSeat(int row, int col) {
        if (row < 1 || row > rows || col < 1 || col > columns) {
            throw new IllegalArgumentException("Invalid seat coordinates");
        }
        if (seats[row - 1][col - 1]) {
            return false;
        }
        seats[row - 1][col - 1] = true;
        return true;
    }

    public int getAvailableSeats() {
        int count = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < columns; j++) {
                if (!seats[i][j]) {
                    count++;
                }
            }
        }
        return count;
    }

    public int[] getBestAvailableSeat() {
        for (int r = 0; r < rows; r++) {
            for (int c : columnOrder) {
                if (!seats[r][c]) {
