public class UriValidator {
    public static Map<String, Object> processContentUri(String uriString) {
        Map<String, Object> result = new HashMap<>();
        result.put("isValid", true);
        result.put("type", "UNKNOWN");

        if (uriString == null || uriString.isEmpty()) {
            result.put("authority", "");
            result.put("path", "");
            return result;
        }

        if (uriString.startsWith("content://")) {
            String withoutScheme = uriString.substring("content://".length());
            int slashIndex = withoutScheme.indexOf('/');
            if (slashIndex == -1) {
                result.put("authority", withoutScheme);
                result.put("path", "");
            } else {
                result.put("authority", withoutScheme.substring(0, slashIndex));
                result.put("path", withoutScheme.substring(slashIndex));
            }
        } else {
            result.put("authority", "");
            result.put("path", uriString);
        }

        return result;
    }
}

