import java.net.URI;
import java.net.URISyntaxException;
import java.util.HashMap;
import java.util.Map;

public class UriValidator {
    public static Map<String, Object> processContentUri(String uriString) throws URISyntaxException {
        Map<String, Object> result = new HashMap<>();

        // Parse the URI using java.net.URI - this will throw URISyntaxException if malformed
        URI uri = new URI(uriString);

        // Validate that the scheme is exactly 'content'
        if (!"content".equals(uri.getScheme())) {
            throw new IllegalArgumentException("URI scheme must be 'content'");
        }

        // Validate that the authority is exactly 'com.project.notepad.provider'
        String authority = uri.getAuthority();
        if (!"com.project.notepad.provider".equals(authority)) {
            throw new IllegalArgumentException("Invalid authority");
        }

        // Validate that the path is not null or empty
        String path = uri.getPath();
        if (path == null || path.isEmpty() || path.equals("/")) {
            throw new IllegalArgumentException("URI path cannot be empty");
        }

        // Remove any leading slash from the path
        if (path.startsWith("/")) {
            path = path.substring(1);
        }

        // Validate path and determine type
        String type = determineUriType(path);

        // If we reach here, the URI is valid and has the correct scheme and authority
        result.put("isValid", true);
        result.put("authority", authority);
        result.put("path", path);
        result.put("type", type);

        return result;
    }

    private static String determineUriType(String path) {
        switch (path) {
            case "notes":
                return "NOTE";
            case "courses":
                return "COURSE";
            case "notes_courses_joined":
                return "JOINED";
            default:
                throw new IllegalArgumentException("Invalid path: " + path + 
                    ". Must be one of: 'notes', 'courses', 'notes_courses_joined'");
        }
    }
}
