        return paginate(items, page, rowsPerPage, key, null, true);
    }

    public PaginatedResult<T> paginate(List<T> items, int page, int rowsPerPage, String key, String sortBy, boolean ascending) {
        if (items == null) {
            items = Collections.emptyList();
        }

        List<T> filteredItems = items;
        if (key != null && !key.trim().isEmpty()) {
            filteredItems = filterItems(items, key.trim());
        }

        if (sortBy != null && !sortBy.trim().isEmpty()) {
            filteredItems = sortItems(filteredItems, sortBy.trim(), ascending);
        }

        int total = filteredItems.size();
        int startIndex = (page - 1) * rowsPerPage;

        if (startIndex < 0 || startIndex >= total || rowsPerPage <= 0) {
            return new PaginatedResult<>(Collections.emptyList(), total);
        }

        int endIndex = Math.min(startIndex + rowsPerPage, total);
        List<T> pageItems = filteredItems.subList(startIndex, endIndex);

        return new PaginatedResult<>(new ArrayList<>(pageItems), total);
    }

    private List<T> filterItems(List<T> items, String key) {
        List<T> filtered = new ArrayList<>();
        String lowerKey = key.toLowerCase();

        for (T item : items) {
            if (item != null) {
                String itemStr = item.toString().toLowerCase();
                if (itemStr.contains(lowerKey)) {
                    filtered.add(item);
                }
            }
        }

        return filtered;
    }

    private List<T> sortItems(List<T> items, String sortBy, boolean ascending) {
        if (items.isEmpty()) {
            return items;
        }

        List<T> sortedList = new ArrayList<>(items);
        Class<?> clazz = items.get(0).getClass();

        try {
            Field field = clazz.getDeclaredField(sortBy);
            field.setAccessible(true);

            Comparator<T> comparator = (a, b) -> {
                try {
                    Comparable<Object> valueA = (Comparable<Object>) field.get(a);
                    Comparable<Object> valueB = (Comparable<Object>) field.get(b);

                    if (valueA == null && valueB == null) return 0;
                    if (valueA == null) return ascending ? -1 : 1;
                    if (valueB == null) return ascending ? 1 : -1;

                    return ascending ? valueA.compareTo(valueB) : valueB.compareTo(valueA);
                } catch (IllegalAccessException e) {
                    return 0;
                }
            };

            sortedList.sort(comparator);
        } catch (NoSuchFieldException | SecurityException e) {
            // Return unsorted list if field doesn't exist or is inaccessible
        }

        return sortedList;
    }

    public static class PaginatedResult<T> {
        private final List<T> items;
        private final int total;

        public PaginatedResult(List<T> items, int total) {
            this.items = new ArrayList<>(items);
            this.total = total;
        }

        public List<T> getItems() {
            return new ArrayList<>(items);
        }

        public int getTotal() {
            return total;
