class MatrixProcessor {
    public MatrixResult processMatrix(int[][] matrix) {
        if (matrix == null || matrix.length == 0 || matrix[0].length == 0) {
            throw new IllegalArgumentException("Matrix cannot be null or empty");
        }

        long startTime = System.currentTimeMillis();
        int[][] originalCopy = deepCopy(matrix);
        int zeroCount = countZeros(matrix);

        int rows = matrix.length;
        int cols = matrix[0].length;
        boolean[] zeroRows = new boolean[rows];
        boolean[] zeroCols = new boolean[cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (matrix[i][j] == 0) {
                    zeroRows[i] = true;
                    zeroCols[j] = true;
                }
            }
        }

        int[][] resultMatrix = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (zeroRows[i] || zeroCols[j]) {
                    resultMatrix[i][j] = 0;
                } else {
                    resultMatrix[i][j] = matrix[i][j];
                }
            }
        }

        long processingTime = System.currentTimeMillis() - startTime;
        return new MatrixResult(originalCopy, zeroCount, processingTime, resultMatrix);
    }

    private int[][] deepCopy(int[][] matrix) {
        if (matrix == null) {
            return null;
        }
        int[][] copy = new int[matrix.length][];
        for (int i = 0; i < matrix.length; i++) {
            copy[i] = new int[matrix[i].length];
            System.arraycopy(matrix[i], 0, copy[i], 0, matrix[i].length);
        }
        return copy;
    }

    private int countZeros(int[][] matrix) {
        int count = 0;
        for (int[] row : matrix) {
            for (int value : row) {
                if (value == 0) {
                    count++;
                }
            }
        }
        return count;
    }

    static class MatrixResult {
        final int[][] originalMatrix;
        final int zeroCount;
        final long processingTimeMs;
        final int[][] processedMatrix;

        public MatrixResult(int[][] originalMatrix, int zeroCount, long processingTimeMs, int[][] processedMatrix) {
            this.originalMatrix = originalMatrix;
            this.zeroCount = zeroCount;
            this.processingTimeMs = processingTimeMs;
            this.processedMatrix = processedMatrix;
        }
    }
}

