class MatrixProcessor {
    public MatrixResult processMatrix(int[][] matrix, boolean useSpaceEfficient) {
        if (matrix == null || matrix.length == 0 || matrix[0].length == 0) {
            throw new IllegalArgumentException("Matrix cannot be null or empty");
        }

        long startTime = System.currentTimeMillis();
        int[][] originalCopy = deepCopy(matrix);
        int zeroCount = countZeros(matrix);
        int[][] resultMatrix;
        String methodUsed;

        if (useSpaceEfficient) {
            resultMatrix = zeroMatrixSpaceEfficient(matrix);
            methodUsed = "Space-Efficient";
        } else {
            resultMatrix = zeroMatrixWithSets(matrix);
            methodUsed = "HashSet-Based";
        }

        long processingTime = System.currentTimeMillis() - startTime;
        return new MatrixResult(originalCopy, zeroCount, processingTime, resultMatrix, methodUsed);
    }

    private int[][] zeroMatrixWithSets(int[][] matrix) {
        int rows = matrix.length;
        int cols = matrix[0].length;
        boolean[] zeroRows = new boolean[rows];
        boolean[] zeroCols = new boolean[cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (matrix[i][j] == 0) {
                    zeroRows[i] = true;
                    zeroCols[j] = true;
                }
            }
        }

        int[][] result = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (zeroRows[i] || zeroCols[j]) {
                    result[i][j] = 0;
                } else {
                    result[i][j] = matrix[i][j];
                }
            }
        }

        return result;
    }

    private int[][] zeroMatrixSpaceEfficient(int[][] matrix) {
        int rows = matrix.length;
        int cols = matrix[0].length;
        boolean firstRowHasZero = false;
        boolean firstColHasZero = false;

        for (int j = 0; j < cols; j++) {
            if (matrix[0][j] == 0) {
                firstRowHasZero = true;
                break;
            }
        }

        for (int i = 0; i < rows; i++) {
            if (matrix[i][0] == 0) {
                firstColHasZero = true;
                break;
            }
        }

        for (int i = 1; i < rows; i++) {
            for (int j = 1; j < cols; j++) {
                if (matrix[i][j] == 0) {
                    matrix[i][0] = 0;
                    matrix[0][j] = 0;
                }
            }
        }

        for (int i = 1; i < rows; i++) {
            for (int j = 1; j < cols; j++) {
                if (matrix[i][0] == 0 || matrix[0][j] == 0) {
                    matrix[i][j] = 0;
                }
            }
        }

        if (firstRowHasZero) {
            for (int j = 0; j < cols; j++) {
                matrix[0][j] = 0;
            }
        }

        if (firstColHasZero) {
            for (int i = 0; i < rows; i++) {
                matrix[i][0] = 0;
            }
        }

        return matrix;
    }

