            throw new IllegalArgumentException("Input string cannot be null");
        }

        Map<String, Object> results = new LinkedHashMap<>();

        // Reverse the entire string
        String reversed = new StringBuilder(input).reverse().toString();
        results.put("reversedString", reversed);

        // Reverse each word individually while maintaining word order
        if (input.isEmpty()) {
            results.put("wordsReversed", "");
        } else {
            String[] words = input.split(" ");
            StringBuilder wordsReversedBuilder = new StringBuilder();
            for (int i = 0; i < words.length; i++) {
                wordsReversedBuilder.append(new StringBuilder(words[i]).reverse());
                if (i < words.length - 1) {
                    wordsReversedBuilder.append(" ");
                }
            }
            results.put("wordsReversed", wordsReversedBuilder.toString());
