import java.util.*;

class TwoSatSolver {
    private List<int[]> edges;
    private Set<Integer> variables;

    public TwoSatSolver() {
        edges = new ArrayList<>();
        variables = new HashSet<>();
    }

    public void addClause(int a, int b) {
        edges.add(new int[]{-a, b});
        edges.add(new int[]{-b, a});
        variables.add(Math.abs(a));
        variables.add(Math.abs(b));
    }

    public boolean isSatisfiable() {
        if (variables.isEmpty()) {
            return true;
        }

        int n = Collections.max(variables);
        int numNodes = 2 * n;
        List<Integer>[] graph = new ArrayList[numNodes];
        List<Integer>[] reverseGraph = new ArrayList[numNodes];

        for (int i = 0; i < numNodes; i++) {
            graph[i] = new ArrayList<>();
            reverseGraph[i] = new ArrayList<>();
        }

        for (int[] edge : edges) {
            int u = getNodeIndex(edge[0], n);
            int v = getNodeIndex(edge[1], n);
            if (u != -1 && v != -1) {
                graph[u].add(v);
                reverseGraph[v].add(u);
            }
        }

        boolean[] visited = new boolean[numNodes];
        Deque<Integer> orderStack = new ArrayDeque<>();
        int[] nextIndex = new int[numNodes];

        for (int i = 0; i < numNodes; i++) {
            if (!visited[i]) {
                Deque<Integer> stack = new ArrayDeque<>();
                stack.push(i);
                visited[i] = true;
                while (!stack.isEmpty()) {
                    int node = stack.peek();
                    if (nextIndex[node] < graph[node].size()) {
                        int neighbor = graph[node].get(nextIndex[node]++);
                        if (!visited[neighbor]) {
                            visited[neighbor] = true;
                            stack.push(neighbor);
                        }
                    } else {
                        stack.pop();
                        orderStack.push(node);
                    }
                }
            }
        }

        Arrays.fill(visited, false);
        int[] comp = new int[numNodes];
        Arrays.fill(comp, -1);
        int compId = 0;

        while (!orderStack.isEmpty()) {
            int node = orderStack.pop();
            if (!visited[node]) {
                Deque<Integer> stack = new ArrayDeque<>();
                stack.push(node);
                visited[node] = true;
                comp[node] = compId;
                while (!stack.isEmpty()) {
                    int current = stack.pop();
                    for (int neighbor : reverseGraph[current]) {
                        if (!visited[neighbor]) {
                            visited[neighbor] = true;
                            comp[neighbor] = compId;
                            stack.push(neighbor);
                        }
                    }
                }
                compId++;
            }
        }

        for (int i = 1; i <= n; i++) {
            int pos = getNodeIndex(i, n);
            int neg = getNodeIndex(-i, n);
            if (comp[pos] == comp[neg]) {
                return false;
            }
        }

        return true;
    }

    private int getNodeIndex(int literal, int n) {
        int abs = Math.abs(literal);
        if (abs < 1 || abs > n) {
            return -1;
        }
        if (literal > 0) {
            return 2 * (abs - 1);
        } else {
            return 2 * (abs - 1) + 1;
        }
    }
}

