    private Set<Integer> variables;

    public TwoSatSolver() {
        edges = new ArrayList<>();
        variables = new HashSet<>();
    }

    public void addClause(int a, int b) {
        edges.add(new int[]{-a, b});
        edges.add(new int[]{-b, a});
        variables.add(Math.abs(a));
        variables.add(Math.abs(b));
    }

    public boolean isSatisfiable() {
        if (variables.isEmpty()) {
            return true;
        }

        int n = Collections.max(variables);
        int numNodes = 2 * n;
        List<Integer>[] graph = new ArrayList[numNodes];
        List<Integer>[] reverseGraph = new ArrayList[numNodes];

        for (int i = 0; i < numNodes; i++) {
            graph[i] = new ArrayList<>();
            reverseGraph[i] = new ArrayList<>();
        }

        for (int[] edge : edges) {
            int u = getNodeIndex(edge[0], n);
            int v = getNodeIndex(edge[1], n);
            if (u != -1 && v != -1) {
                graph[u].add(v);
                reverseGraph[v].add(u);
            }
        }

        // First pass: DFS on reverse graph to compute finishing times
        boolean[] visited = new boolean[numNodes];
        Deque<Integer> orderStack = new ArrayDeque<>();
        int[] nextIndex = new int[numNodes];

