import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

public class EnhancedOptions {
    private Map<String, Object> options;
    private Set<String> requiredOptions;
    private Map<String, Object> defaultOptions;
    private Map<String, Set<String>> optionDependencies;

    public EnhancedOptions() {
        options = new HashMap<>();
        requiredOptions = new HashSet<>();
        defaultOptions = new HashMap<>();
        optionDependencies = new HashMap<>();

        defaultOptions.put("header_footer", true);
        defaultOptions.put("compact", false);
        defaultOptions.put("safe", 0);

        requiredOptions.add("backend");
        requiredOptions.add("doctype");

        Set<String> templateDeps = new HashSet<>();
        templateDeps.add("template_dirs");
        optionDependencies.put("template_engine", templateDeps);
    }

    public void setOption(String key, Object value) {
        options.put(key, value);
    }

    public Object getOption(String key) {
        return options.getOrDefault(key, defaultOptions.get(key));
    }
}

