                if (nanos <= 0) {
                    return false;
                }
                nanos = notFull.awaitNanos(nanos);
            }
            queue.add(element);
            totalAdded++;
            // Update max size if needed
            if (queue.size() > maxSize) {
                maxSize = queue.size();
            }
            notEmpty.signal();
            return true;
        } finally {
            lock.unlock();
        }
    }

    public T poll(long timeout, TimeUnit unit) throws InterruptedException {
        long nanos = unit.toNanos(timeout);
        lock.lock();
        try {
            while (queue.isEmpty()) {
                if (nanos <= 0) {
                    return null;
                }
                nanos = notEmpty.awaitNanos(nanos);
            }
            T item = queue.remove();
            totalRemoved++;
            notFull.signal();
            return item;
        } finally {
            lock.unlock();
        }
    }

    public T peek() {
        lock.lock();
        try {
            return queue.peek();
        } finally {
            lock.unlock();
        }
    }

    public int size() {
        lock.lock();
        try {
            return queue.size();
        } finally {
            lock.unlock();
        }
    }

    public int remainingCapacity() {
        lock.lock();
        try {
            return capacity - queue.size();
        } finally {
            lock.unlock();
        }
    }

    public int clear() {
        lock.lock();
        try {
            int removedCount = queue.size();
            totalRemoved += removedCount;
            queue.clear();
            // Signal all waiting producers since we've made space
            notFull.signalAll();
            return removedCount;
        } finally {
            lock.unlock();
        }
    }

    public String getStats() {
        lock.lock();
        try {
            return String.format("Added: %d, Removed: %d, Current: %d, Max: %d", 
                                totalAdded, totalRemoved, queue.size(), maxSize);
        } finally {
            lock.unlock();
        }
    }
}
