    public static BinaryTreeNode buildTree(BinaryTreeNode[] nodes, int[][] relationships) {
        if (nodes == null || nodes.length == 0) {
            throw new IllegalArgumentException("Invalid input: nodes array must be non-null and non-empty, and all indices in relationships must be valid.");
        }

        // Validate relationships indices
        for (int[] rel : relationships) {
            if (rel == null || rel.length != 3 || 
                rel[0] < 0 || rel[0] >= nodes.length || 
                rel[1] < 0 || rel[1] >= nodes.length) {
                throw new IllegalArgumentException("Invalid input: nodes array must be non-null and non-empty, and all indices in relationships must be valid.");
            }

            char direction = (char) rel[2];
            if (direction != 'L' && direction != 'R') {
                throw new IllegalArgumentException("Invalid input: nodes array must be non-null and non-empty, and all indices in relationships must be valid.");
            }
        }

        // Build the tree
        for (int[] rel : relationships) {
            BinaryTreeNode parent = nodes[rel[0]];
            BinaryTreeNode child = nodes[rel[1]];
            char direction = (char) rel[2];

            if (direction == 'L') {
                parent.left = child;
            } else {
                parent.right = child;
            }
            child.parent = parent;
        }

        return nodes[0];
    }
}

