public class NavalBattleAdapter {
    private Set<String> shipPositions;
    private Set<String> attackPositions;
    private boolean gameOver;
    private String winner;

    public NavalBattleAdapter() {
        this.shipPositions = new HashSet<>();
        this.attackPositions = new HashSet<>();
        this.gameOver = false;
        this.winner = null;
    }

    public void placeShips(List<String> coordinates) {
        if (coordinates == null) {
            throw new IllegalArgumentException("Coordinates list cannot be null");
        }
        if (coordinates.isEmpty()) {
            throw new IllegalArgumentException("Coordinates list cannot be empty");
        }
        shipPositions.addAll(coordinates);
    }

    public HitResult receiveAttack(String coordinate) {
        if (coordinate == null) {
            throw new IllegalArgumentException("Coordinate cannot be null");
        }
        if (coordinate.isEmpty()) {
            throw new IllegalArgumentException("Coordinate cannot be empty");
        }

        attackPositions.add(coordinate);

        if (shipPositions.contains(coordinate)) {
            shipPositions.remove(coordinate);
            if (shipPositions.isEmpty()) {
                gameOver = true;
                winner = "Opponent";
                return HitResult.SUNK;
            }
            return HitResult.HIT;
        } else {
            return HitResult.MISS;
        }
    }

    public GameState getGameState() {
        return new GameState(
            Collections.unmodifiableSet(new HashSet<>(shipPositions)),
            Collections.unmodifiableSet(new HashSet<>(attackPositions)),
            gameOver,
            winner
        );
    }

    public enum HitResult {
        HIT, MISS, SUNK
    }

    public static class GameState {
        private final Set<String> remainingShips;
        private final Set<String> attacksMade;
        private final boolean gameOver;
        private final String winner;

        public GameState(Set<String> remainingShips, Set<String> attacksMade, 
                        boolean gameOver, String winner) {
            this.remainingShips = remainingShips;
            this.attacksMade = attacksMade;
            this.gameOver = gameOver;
            this.winner = winner;
