import java.util.Observable;

public class NavalBattleAdapter extends Observable {
    private Set<String> shipPositions;
    private Set<String> attackPositions;
    private boolean gameOver;
    private String winner;

    public NavalBattleAdapter() {
        this.shipPositions = new HashSet<>();
        this.attackPositions = new HashSet<>();
        this.gameOver = false;
        this.winner = null;
    }

    public void placeShips(List<String> coordinates) {
        if (coordinates == null) {
            throw new IllegalArgumentException("Coordinates list cannot be null");
        }
        if (coordinates.isEmpty()) {
            throw new IllegalArgumentException("Coordinates list cannot be empty");
        }
        shipPositions.addAll(coordinates);
        notifyStateChange(EventType.SHIPS_PLACED, null);
    }

    public HitResult receiveAttack(String coordinate) {
        if (coordinate == null) {
            throw new IllegalArgumentException("Coordinate cannot be null");
        }
        if (coordinate.isEmpty()) {
            throw new IllegalArgumentException("Coordinate cannot be empty");
        }

        attackPositions.add(coordinate);

        if (shipPositions.contains(coordinate)) {
