        // Convert to title case: first character uppercase, rest lowercase
        String firstChar = lettersOnly.substring(0, 1).toUpperCase();
        String restOfString = lettersOnly.substring(1).toLowerCase();
        String result = firstChar + restOfString;

        // Reverse if more than 5 characters
        if (result.length() > 5) {
            result = new StringBuilder(result).reverse().toString();
        }

        // Apply length-based markers
        int length = result.length();
        if (length < 3) {
            return "Short_" + result;
        } else if (length <= 5) {
            return result + "_Medium";
        } else {
            return "Long_" + result + "_Processed";
        }
    }
}

