import java.util.*;
import java.util.concurrent.*;

class MessageProducer {
    private BlockingQueue<String> queue;
    private List<String> sentMessages;
    private int maxRetries;
    private long retryDelay;

    public MessageProducer() {
        this(new LinkedBlockingQueue<>(), 3, 100);
    }

    public MessageProducer(BlockingQueue<String> queue, int maxRetries, long retryDelayMillis) {
        this.queue = queue;
        this.sentMessages = new ArrayList<>();
        this.maxRetries = maxRetries;
        this.retryDelay = retryDelayMillis;
    }

    public void sendMessages(String prefix, int count) {
        for (int i = 1; i <= count; i++) {
            String message = prefix + " " + i;
            boolean messageSent = false;

            for (int attempt = 0; attempt < maxRetries && !messageSent; attempt++) {
                try {
                    if (queue.offer(message, 100, TimeUnit.MILLISECONDS)) {
                        sentMessages.add(message);
                        messageSent = true;
                    } else if (attempt < maxRetries - 1) {
                        Thread.sleep(retryDelay);
                    }
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    throw new RuntimeException("Message sending interrupted", e);
                }
            }

            if (!messageSent) {
                throw new RuntimeException("Failed to send message after " + maxRetries + " attempts: " + message);
            }
        }
    }

    public BlockingQueue<String> getMessageQueue() {
        return queue;
    }
}

