import java.util.ArrayList;
import java.util.List;

public class AdditionChainFinder {
    public List<Integer> findShortestAdditionChain(int target) {
        if (target < 1) {
            throw new IllegalArgumentException("Target number must be at least 1, but was: " + target);
        }
        if (target == 1) {
            List<Integer> chain = new ArrayList<>();
            chain.add(1);
            return chain;
        }

        int minLength = (int) (Math.log(target) / Math.log(2)) + 1;
        List<List<Integer>> chains = new ArrayList<>();

        for (int depth = minLength; depth <= 2 * minLength; depth++) {
            List<Integer> chain = new ArrayList<>();
            chain.add(1);
            dfs(chain, depth, target, chains);
            if (!chains.isEmpty()) {
                return findLexSmallestChain(chains);
            }
        }

        return null;
    }

    private void dfs(List<Integer> chain, int depth, int target, List<List<Integer>> results) {
        int last = chain.get(chain.size() - 1);
        if (chain.size() == depth) {
            if (last == target) {
                results.add(new ArrayList<>(chain));
            }
            return;
        }

        int remainingSteps = depth - chain.size();
        if (last * (1L << remainingSteps) < target) {
            return;
        }
        if (last > target) {
            return;
        }

        for (int i = chain.size() - 1; i >= 0; i--) {
            int num = chain.get(i);
            int next = last + num;
            if (next > target) {
                continue;
            }
            chain.add(next);
            dfs(chain, depth, target, results);
            chain.remove(chain.size() - 1);
        }
    }

    private List<Integer> findLexSmallestChain(List<List<Integer>> chains) {
        List<Integer> best = chains.get(0);
        for (List<Integer> chain : chains) {
            if (compareLex(chain, best) < 0) {
                best = chain;
            }
        }
        return best;
    }

    private int compareLex(List<Integer> a, List<Integer> b) {
        for (int i = 0; i < a.size(); i++) {
            int cmp = Integer.compare(a.get(i), b.get(i));
            if (cmp != 0) {
                return cmp;
            }
        }
        return 0;
    }
}

