    private List<LayoutConstraint> constraints;
    private boolean respectAspectRatio;
    private double aspectRatio;

    public EnhancedLayoutManager(List<Component> components, List<LayoutConstraint> constraints,
                               boolean respectAspectRatio, double aspectRatio) {
        this.components = components;
        this.constraints = constraints;
        this.respectAspectRatio = respectAspectRatio;
        this.aspectRatio = aspectRatio;
    }

    public Map<Component, Rectangle> calculateLayout(int containerWidth, int containerHeight) {
        Map<Component, Rectangle> layout = new HashMap<>();
        if (components.isEmpty() || constraints.isEmpty()) {
            return layout;
        }

        double containerAspect = (double) containerWidth / containerHeight;
        int adjustedWidth = containerWidth;
        int adjustedHeight = containerHeight;
        int xOffset = 0;
        int yOffset = 0;

        if (respectAspectRatio) {
            if (containerAspect > aspectRatio) {
                adjustedWidth = (int) (containerHeight * aspectRatio);
                xOffset = (containerWidth - adjustedWidth) / 2;
            } else {
                adjustedHeight = (int) (containerWidth / aspectRatio);
                yOffset = (containerHeight - adjustedHeight) / 2;
