import java.util.ArrayList;
import java.util.List;

public class PianoOctaveManager {
    private int currentOctave;
    private final int minOctave;
    private final int maxOctave;
    private List<OctaveChangeListener> listeners;

    public PianoOctaveManager(int initialOctave, int minOctave, int maxOctave) {
        if (minOctave > maxOctave) {
            throw new IllegalArgumentException("minOctave cannot be greater than maxOctave");
        }
        this.minOctave = minOctave;
        this.maxOctave = maxOctave;
        this.currentOctave = Math.max(minOctave, Math.min(maxOctave, initialOctave));
        this.listeners = new ArrayList<>();
    }

    public int getCurrentOctave() {
        return currentOctave;
    }

    public void setCurrentOctave(int newOctave) {
        setCurrentOctaveInternal(newOctave);
    }

    public boolean incrementOctave() {
        if (currentOctave < maxOctave) {
            setCurrentOctaveInternal(currentOctave + 1);
            return true;
        }
        return false;
    }

    public boolean decrementOctave() {
        if (currentOctave > minOctave) {
            setCurrentOctaveInternal(currentOctave - 1);
            return true;
        }
        return false;
    }

    private void setCurrentOctaveInternal(int newOctave) {
        int oldOctave = currentOctave;
        currentOctave = Math.max(minOctave, Math.min(maxOctave, newOctave));
        if (oldOctave != currentOctave) {
            notifyListeners(oldOctave, currentOctave);
        }
    }

    private void notifyListeners(int oldOctave, int newOctave) {
        for (OctaveChangeListener listener : listeners) {
            listener.onOctaveChanged(oldOctave, newOctave);
        }
    }

    public void addOctaveChangeListener(OctaveChangeListener listener) {
        listeners.add(listener);
    }

    public void removeOctaveChangeListener(OctaveChangeListener listener) {
        listeners.remove(listener);
    }

    public interface OctaveChangeListener {
        void onOctaveChanged(int oldOctave, int newOctave);
    }
}

