import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class UserManager {
    private List<User> users;
    private Map<String, Integer> failedAttempts;
    private Map<String, Boolean> lockedAccounts;

    public UserManager() {
        this.users = new ArrayList<>();
        this.failedAttempts = new HashMap<>();
        this.lockedAccounts = new HashMap<>();
    }

    public Map<String, Object> registerUser(User user) {
        Map<String, Object> response = new HashMap<>();

        if (user.getUsername() == null || user.getUsername().trim().isEmpty()) {
            response.put("success", false);
            response.put("message", "Username cannot be empty");
            return response;
        }

        if (user.getPassword() == null || user.getPassword().trim().isEmpty()) {
            response.put("success", false);
            response.put("message", "Password cannot be empty");
            return response;
        }

        String usernameLower = user.getUsername().toLowerCase();
        for (User existingUser : users) {
            if (existingUser.getUsername().toLowerCase().equals(usernameLower)) {
                response.put("success", false);
                response.put("message", "Username already exists");
                return response;
            }
        }

        users.add(user);
        failedAttempts.put(usernameLower, 0);
        lockedAccounts.put(usernameLower, false);
        response.put("success", true);
        response.put("message", "User registered successfully");
        return response;
    }

    public Map<String, Object> loginUser(String username, String password) {
        Map<String, Object> response = new HashMap<>();
        String usernameLower = username.toLowerCase();

        // Check if account is locked
        if (lockedAccounts.getOrDefault(usernameLower, false)) {
            response.put("success", false);
            response.put("message", "Account is locked due to too many failed attempts");
            return response;
        }

        // Find user with matching username (case-insensitive) and password
        User foundUser = null;
        for (User user : users) {
            if (user.getUsername().equalsIgnoreCase(username) && 
                user.getPassword().equals(password)) {
                foundUser = user;
                break;
            }
        }

        if (foundUser != null) {
            // Successful login - reset failed attempts
            failedAttempts.put(usernameLower, 0);
            response.put("success", true);
            response.put("message", "Login successful");
            response.put("user", foundUser);
        } else {
            // Failed login - increment attempt counter
            int attempts = failedAttempts.getOrDefault(usernameLower, 0) + 1;
            failedAttempts.put(usernameLower, attempts);

            // Check if account should be locked
            if (attempts >= 3) {
                lockedAccounts.put(usernameLower, true);
                response.put("success", false);
                response.put("message", "Account locked due to too many failed attempts");
            } else {
                response.put("success", false);
                response.put("message", "Invalid credentials");
                response.put("attemptsRemaining", 3 - attempts);
            }
        }

        return response;
    }
}

