import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

public class UserManager {
    private List<User> users;
    private Map<String, Integer> failedAttempts;
    private Map<String, Boolean> lockedAccounts;

    public UserManager() {
        this.users = new ArrayList<>();
        this.failedAttempts = new HashMap<>();
        this.lockedAccounts = new HashMap<>();
    }

    // ... existing registerUser and loginUser methods ...

    public List<User> searchUsers(String username, String email, int page, int pageSize) {
        // Filter users based on partial matching criteria
        List<User> filteredUsers = users.stream()
                .filter(user -> username == null || user.getUsername().toLowerCase().contains(username.toLowerCase()))
                .filter(user -> email == null || user.getEmail().toLowerCase().contains(email.toLowerCase()))
                .collect(Collectors.toList());

        // Calculate pagination values
        int totalUsers = filteredUsers.size();
        int totalPages = (int) Math.ceil((double) totalUsers / pageSize);

        // Validate page number
        if (page < 1 || page > totalPages) {
            return new ArrayList<>();
        }

        // Calculate start and end indices
        int startIndex = (page - 1) * pageSize;
        int endIndex = Math.min(startIndex + pageSize, totalUsers);

        // Return paginated results
        return filteredUsers.subList(startIndex, endIndex);
    }
}

