import java.util.*;
import java.util.stream.Collectors;

public class DataMatcher {
    public Map<String, List<String[]>> enhancedMatch(List<String[]> dataset1, List<String[]> dataset2, int matchStrategy, int[] keyIndices) {
        Map<String, List<String[]>> result = new HashMap<>();
        List<String[]> matched = new ArrayList<>();
        List<String[]> unmatched1 = new ArrayList<>();
        List<String[]> unmatched2 = new ArrayList<>();

        if (matchStrategy != 1) {
            // For now, only strategy 1 is implemented
            result.put("matched", matched);
            result.put("unmatched1", dataset1);
            result.put("unmatched2", dataset2);
            return result;
        }

        // Build a map for dataset2 with trimmed keys
        Map<String, List<String[]>> map2 = new HashMap<>();
        for (String[] record : dataset2) {
            String key = buildKey(record, keyIndices);
            map2.computeIfAbsent(key, k -> new ArrayList<>()).add(record);
        }

        // Process dataset1
        for (String[] record1 : dataset1) {
            String key = buildKey(record1, keyIndices);
            List<String[]> matches = map2.get(key);
            if (matches != null && !matches.isEmpty()) {
                String[] record2 = matches.remove(0);
                matched.add(concatArrays(record1, record2));
            } else {
                unmatched1.add(record1);
            }
        }

        // Collect remaining unmatched records from dataset2
        unmatched2.addAll(map2.values().stream().flatMap(List::stream).collect(Collectors.toList()));

        result.put("matched", matched);
        result.put("unmatched1", unmatched1);
        result.put("unmatched2", unmatched2);
        return result;
    }

    private String buildKey(String[] record, int[] keyIndices) {
        return Arrays.stream(keyIndices)
                .mapToObj(i -> record[i].trim())
                .collect(Collectors.joining("|"));
    }

    private String[] concatArrays(String[] arr1, String[] arr2) {
        String[] combined = new String[arr1.length + arr2.length];
        System.arraycopy(arr1, 0, combined, 0, arr1.length);
        System.arraycopy(arr2, 0, combined, arr1.length, arr2.length);
        return combined;
    }
}

