import java.util.ArrayList;
import java.util.List;

public class PaginationManager {

    public static class PaginationResult {
        private int totalItems;
        private int pageSize;
        private int currentPage;
        private int totalPages;
        private int startItem;
        private int endItem;
        private List<Integer> visiblePages;

        public PaginationResult(int totalItems, int pageSize, int currentPage, int totalPages, 
                               int startItem, int endItem, List<Integer> visiblePages) {
            this.totalItems = totalItems;
            this.pageSize = pageSize;
            this.currentPage = currentPage;
            this.totalPages = totalPages;
            this.startItem = startItem;
            this.endItem = endItem;
            this.visiblePages = visiblePages;
        }

        // Getters for all fields (omitted for brevity)
    }

    public PaginationResult calculatePagination(int totalItems, int currentPage, int pageSize) {
        // Calculate total pages using ceiling division
        int totalPages = (int) Math.ceil((double) totalItems / pageSize);
        totalPages = Math.max(totalPages, 0); // Ensure non-negative

        // Clamp currentPage within valid range [1, totalPages]
        if (totalPages == 0) {
            currentPage = 0;
        } else {
            currentPage = Math.max(1, Math.min(currentPage, totalPages));
        }

        // Calculate start and end items (1-based)
        int startItem = (currentPage - 1) * pageSize + 1;
        if (totalItems == 0 || currentPage == 0) {
            startItem = 0;
        }
        int endItem = Math.min(currentPage * pageSize, totalItems);
        if (currentPage == 0) {
            endItem = 0;
        }

        // Generate visible pages list [1, 2, ..., totalPages]
        List<Integer> visiblePages = new ArrayList<>();
        for (int i = 1; i <= totalPages; i++) {
            visiblePages.add(i);
        }

        return new PaginationResult(
            totalItems, pageSize, currentPage, totalPages,
            startItem, endItem, visiblePages
        );
    }
}

