public class PaginationManager {

    public static class PaginationResult {
        private int totalItems;
        private int pageSize;
        private int currentPage;
        private int totalPages;
        private int startItem;
        private int endItem;
        private List<Integer> visiblePages;

        public PaginationResult(int totalItems, int pageSize, int currentPage, int totalPages, 
                               int startItem, int endItem, List<Integer> visiblePages) {
            this.totalItems = totalItems;
            this.pageSize = pageSize;
            this.currentPage = currentPage;
            this.totalPages = totalPages;
            this.startItem = startItem;
            this.endItem = endItem;
            this.visiblePages = visiblePages;
        }
    }

    public PaginationResult calculatePagination(int totalItems, int currentPage, int pageSize) {
        if (totalItems < 0) {
            throw new IllegalArgumentException("totalItems must not be negative");
        }
        if (pageSize <= 0) {
            throw new IllegalArgumentException("pageSize must be greater than zero");
        }
        if (currentPage <= 0) {
            throw new IllegalArgumentException("currentPage must be greater than zero");
        }

        if (totalItems == 0) {
            return new PaginationResult(0, pageSize, 1, 0, 0, 0, new ArrayList<>());
        }

        int totalPages = (int) Math.ceil((double) totalItems / pageSize);
        currentPage = Math.min(currentPage, totalPages);

        int startItem = (currentPage - 1) * pageSize + 1;
        int endItem = Math.min(currentPage * pageSize, totalItems);

        List<Integer> visiblePages = calculateVisiblePages(totalPages, currentPage);

        return new PaginationResult(totalItems, pageSize, currentPage, totalPages, 
                                  startItem, endItem, visiblePages);
    }

    private List<Integer> calculateVisiblePages(int totalPages, int currentPage) {
        List<Integer> visiblePages = new ArrayList<>();
        if (totalPages <= 0) {
            return visiblePages;
        }

        int leftWindow = Math.max(1, currentPage - 2);
        int rightWindow = Math.min(totalPages, currentPage + 2);

        boolean showLeftEllipsis = leftWindow > 2;
        boolean showRightEllipsis = rightWindow < totalPages - 1;

        visiblePages.add(1);

        if (showLeftEllipsis) {
            visiblePages.add(-1);
        }

        for (int i = leftWindow; i <= rightWindow; i++) {
            if (i != 1 && i != totalPages) {
                visiblePages.add(i);
            }
        }

        if (showRightEllipsis) {
            visiblePages.add(-1);
        }

        if (totalPages > 1) {
            visiblePages.add(totalPages);
        }

        return visiblePages;
    }
}

