public class PathFinder {

    public static class Result {
        private final int totalUniquePaths;

        public Result(int totalUniquePaths) {
            this.totalUniquePaths = totalUniquePaths;
        }

        public int getTotalUniquePaths() {
            return totalUniquePaths;
        }
    }

    public Result findUniquePathsWithAnalysis(int[][] grid) {
        if (grid == null || grid.length == 0 || grid[0].length == 0) {
            return new Result(0);
        }

        int m = grid.length;
        int n = grid[0].length;

        // If start or end is blocked
        if (grid[0][0] == 0 || grid[m-1][n-1] == 0) {
            return new Result(0);
        }

        int[][] dp = new int[m][n];
        dp[0][0] = 1;

        // Initialize first column
        for (int i = 1; i < m; i++) {
            dp[i][0] = (grid[i][0] == 1) ? dp[i-1][0] : 0;
        }

        // Initialize first row
        for (int j = 1; j < n; j++) {
            dp[0][j] = (grid[0][j] == 1) ? dp[0][j-1] : 0;
        }

        // Fill the DP table
        for (int i = 1; i < m; i++) {
            for (int j = 1; j < n; j++) {
                if (grid[i][j] == 1) {
                    dp[i][j] = dp[i-1][j] + dp[i][j-1];
                } else {
                    dp[i][j] = 0;
                }
            }
        }

        return new Result(dp[m-1][n-1]);
    }
}

