import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class PathFinder {

    public static class PathAnalysis {
        public final int totalPaths;
        public final int maxPathLength;
        public final int minPathLength;
        public final List<String> samplePath;

        public PathAnalysis(int totalPaths, int maxPathLength, int minPathLength, List<String> samplePath) {
            this.totalPaths = totalPaths;
            this.maxPathLength = maxPathLength;
            this.minPathLength = minPathLength;
            this.samplePath = samplePath;
        }

        @Override
        public String toString() {
            return "Total Paths: " + totalPaths + "\n" +
                   "Max Path Length: " + maxPathLength + "\n" +
                   "Min Path Length: " + minPathLength + "\n" +
                   "Sample Path: " + samplePath;
        }
    }

    public PathAnalysis findUniquePathsWithAnalysis(int[][] grid) {
        if (grid == null || grid.length == 0 || grid[0].length == 0) {
            return new PathAnalysis(0, 0, 0, new ArrayList<>());
        }

        int m = grid.length;
        int n = grid[0].length;

        // Check if start or end is blocked
        if (grid[0][0] == 0 || grid[m-1][n-1] == 0) {
            return new PathAnalysis(0, 0, 0, new ArrayList<>());
        }

        int[][] dp = new int[m][n];
        dp[0][0] = 1;

        // Initialize first column
        for (int i = 1; i < m; i++) {
            dp[i][0] = (grid[i][0] == 1) ? dp[i-1][0] : 0;
        }

        // Initialize first row
        for (int j = 1; j < n; j++) {
            dp[0][j] = (grid[0][j] == 1) ? dp[0][j-1] : 0;
        }

        // Fill DP table
        for (int i = 1; i < m; i++) {
            for (int j = 1; j < n; j++) {
                if (grid[i][j] == 1) {
                    dp[i][j] = dp[i-1][j] + dp[i][j-1];
                } else {
                    dp[i][j] = 0;
                }
            }
        }

        int totalPaths = dp[m-1][n-1];

        // Handle case with no paths
        if (totalPaths == 0) {
            return new PathAnalysis(0, 0, 0, new ArrayList<>());
        }

        // Calculate path length (fixed for all paths)
        int pathLength = (m - 1) + (n - 1);

        // Reconstruct a sample path
        List<String> samplePath = new ArrayList<>();
        int i = m - 1;
        int j = n - 1;

        while (i > 0 || j > 0) {
            if (i > 0 && dp[i-1][j] > 0) {
                samplePath.add("Down");
                i--;
            } else {
                samplePath.add("Right");
                j--;
            }
        }

        Collections.reverse(samplePath);

        return new PathAnalysis(totalPaths, pathLength, pathLength, samplePath);
    }
}

