import java.util.*;

class GraphAnalyzer {
    private Map<String, List<Edge>> adjacencyList;
    private boolean directed;
    private boolean weighted;

    public GraphAnalyzer(boolean directed, boolean weighted) {
        this.adjacencyList = new HashMap<>();
        this.directed = directed;
        this.weighted = weighted;
    }

    public void addNode(String node) {
        adjacencyList.putIfAbsent(node, new ArrayList<>());
    }

    public void addEdge(String from, String to, int weight) {
        addNode(from);
        addNode(to);

        adjacencyList.get(from).add(new Edge(to, weight));
        if (!directed) {
            adjacencyList.get(to).add(new Edge(from, weight));
        }
    }

    public int getNodeDegree(String node) {
        if (!adjacencyList.containsKey(node)) {
            throw new IllegalArgumentException("Node does not exist: " + node);
        }
        return adjacencyList.get(node).size();
    }

    public boolean hasCycle() {
        Set<String> visited = new HashSet<>();
        Set<String> recStack = new HashSet<>();

        for (String node : adjacencyList.keySet()) {
            if (!visited.contains(node)) {
                if (directed) {
                    if (hasCycleDirected(node, visited, recStack)) {
                        return true;
                    }
                } else {
                    if (hasCycleUndirected(node, null, visited)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    public List<String> findShortestPath(String start, String end) {
        if (!adjacencyList.containsKey(start) || !adjacencyList.containsKey(end)) {
            throw new IllegalArgumentException("Start or end node does not exist");
        }

        // Initialize distance and predecessor maps
        Map<String, Integer> distances = new HashMap<>();
        Map<String, String> predecessors = new HashMap<>();
        PriorityQueue<NodeDistance> priorityQueue = new PriorityQueue<>(Comparator.comparingInt(nd -> nd.distance));

        for (String node : adjacencyList.keySet()) {
            distances.put(node, Integer.MAX_VALUE);
        }
        distances.put(start, 0);
        priorityQueue.add(new NodeDistance(start, 0));

        // Dijkstra's algorithm
        while (!priorityQueue.isEmpty()) {
            NodeDistance current = priorityQueue.poll();
            String currentNode = current.node;

            if (currentNode.equals(end)) {
                break; // Found the shortest path to end
            }

            if (current.distance > distances.get(currentNode)) {
                continue; // Skip if we found a shorter path already
            }

            for (Edge edge : adjacencyList.get(currentNode)) {
                int edgeWeight = weighted ? edge.weight : 1;
                int newDistance = distances.get(currentNode) + edgeWeight;

                if (newDistance < distances.get(edge.target)) {
                    distances.put(edge.target, newDistance);
                    predecessors.put(edge.target, currentNode);
                    priorityQueue.add(new NodeDistance(edge.target, newDistance));
                }
            }
        }

        // Reconstruct path if one exists
        if (distances.get(end) == Integer.MAX_VALUE) {
            return new ArrayList<>(); // No path exists
        }

        List<String> path = new ArrayList<>();
        String current = end;
        while (current != null) {
            path.add(0, current);
            current = predecessors.get(current);
        }

        return path;
    }

    private boolean hasCycleDirected(String node, Set<String> visited, Set<String> recStack) {
        if (recStack.contains(node)) {
            return true;
        }

        if (visited.contains(node)) {
            return false;
        }

        visited.add(node);
        recStack.add(node);

        for (Edge edge : adjacencyList.get(node)) {
            if (hasCycleDirected(edge.target, visited, recStack)) {
                return true;
            }
        }

        recStack.remove(node);
        return false;
    }

    private boolean hasCycleUndirected(String node, String parent, Set<String> visited) {
        visited.add(node);

        for (Edge edge : adjacencyList.get(node)) {
            String neighbor = edge.target;

            if (!visited.contains(neighbor)) {
                if (hasCycleUndirected(neighbor, node, visited)) {
                    return true;
                }
            } else if (!neighbor.equals(parent)) {
                return true;
            }
        }
        return false;
    }

    static class Edge {
        String target;
        int weight;

        public Edge(String target, int weight) {
            this.target = target;
            this.weight = weight;
        }
    }

    static class NodeDistance {
        String node;
        int distance;

        public NodeDistance(String node, int distance) {
            this.node = node;
            this.distance = distance;
        }
    }
}

