import java.util.ArrayList;
import java.util.List;

class TaskManager {
    private List<String> tasks;
    private String filename;

    public TaskManager(String filename) {
        this.filename = filename;
        this.tasks = new ArrayList<>();
    }

    public boolean addTask(String taskDescription) {
        if (taskDescription == null || taskDescription.trim().isEmpty()) {
            return false;
        }
        int taskNumber = tasks.size() + 1;
        tasks.add(taskNumber + ". " + taskDescription.trim());
        return true;
    }

    public boolean deleteTask(String position) {
        if (position.equals("-1")) {
            tasks.clear();
            return true;
        }

        try {
            int index = Integer.parseInt(position);
            if (index < 1 || index > tasks.size()) {
                return false;
            }
            tasks.remove(index - 1);

            // Renumber remaining tasks
            for (int i = 0; i < tasks.size(); i++) {
                String task = tasks.get(i);
                int dotIndex = task.indexOf(". ");
                if (dotIndex != -1) {
                    String description = task.substring(dotIndex + 2);
                    tasks.set(i, (i + 1) + ". " + description);
                } else {
                    tasks.set(i, (i + 1) + ". " + task);
                }
            }
            return true;
        } catch (NumberFormatException e) {
            return false;
        }
    }
}

