import java.util.List;
import java.util.ArrayList;

class PatternGenerator {
    public static List<String> generateSandClock(int size, boolean reverse, boolean useLetters) {
        if (size <= 0) {
            throw new IllegalArgumentException("Size must be positive");
        }

        List<String> result = new ArrayList<>();
        int totalLines = 2 * size - 1;
        char patternChar = useLetters ? 'A' : '*';

        if (!reverse) {
            // Top half: from size down to 1
            for (int i = 0; i < size; i++) {
                int stars = size - i;
                result.add(createLine(stars, size, patternChar));
            }
            // Bottom half: from 2 to size
            for (int i = size - 2; i >= 0; i--) {
                int stars = size - i;
                result.add(createLine(stars, size, patternChar));
            }
        } else {
            // Top half: from 1 to size
            for (int i = 0; i < size; i++) {
                int stars = i + 1;
                result.add(createLine(stars, size, patternChar));
            }
            // Bottom half: from size-1 down to 1
            for (int i = size - 2; i >= 0; i--) {
                int stars = i + 1;
                result.add(createLine(stars, size, patternChar));
            }
        }

        return result;
    }

    private static String createLine(int stars, int size, char patternChar) {
        int leftSpaces = (size - stars) / 2;
        int rightSpaces = size - leftSpaces - stars;
        StringBuilder line = new StringBuilder();
        for (int i = 0; i < leftSpaces; i++) {
            line.append(' ');
        }
        for (int i = 0; i < stars; i++) {
            line.append(patternChar);
        }
        for (int i = 0; i < rightSpaces; i++) {
            line.append(' ');
        }
        return line.toString();
    }
}

