            prevJ.next = nodeI;
            nodeI.next = nextJ;
        }

        return dummy.next;
    }

    public static LinkedListNode createLinkedList(java.util.List<Integer> list) {
        if (list.isEmpty()) return null;
        LinkedListNode head = new LinkedListNode(list.get(0));
        LinkedListNode current = head;
        for (int i = 1; i < list.size(); i++) {
            current.next = new LinkedListNode(list.get(i));
            current = current.next;
        }
        return head;
    }

    public static java.util.List<Integer> linkedListToList(LinkedListNode head) {
        java.util.List<Integer> result = new java.util.ArrayList<>();
        LinkedListNode current = head;
        while (current != null) {
            result.add(current.data);
            current = current.next;
        }
        return result;
    }
}
