import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.util.List;
import java.util.ArrayList;

public class EnhancedFileOperations {
    public static class FileStats {
        public final int lineCount;
        public final int wordCount;
        public final int characterCount;
        public final double averageWordsPerLine;

        public FileStats(int lineCount, int wordCount, int characterCount) {
            this.lineCount = lineCount;
            this.wordCount = wordCount;
            this.characterCount = characterCount;
            this.averageWordsPerLine = lineCount > 0 ? (double) wordCount / lineCount : 0.0;
        }

        @Override
        public String toString() {
            return String.format("Line Count: %d%nWord Count: %d%nCharacter Count: %d%nAverage Words Per Line: %.2f", 
                                 lineCount, wordCount, characterCount, averageWordsPerLine);
        }
    }

    private static List<String> readFileWithValidation(File file) throws IOException {
        if (file == null) {
            throw new IllegalArgumentException("File cannot be null");
        }
        if (!file.exists()) {
            throw new IOException("File does not exist: " + file.getAbsolutePath());
        }
        if (!file.canRead()) {
            throw new IOException("Cannot read file: " + file.getAbsolutePath());
        }
        return Files.readAllLines(file.toPath());
    }

    public static FileStats analyzeFileContent(File file) throws IOException {
        List<String> lines = readFileWithValidation(file);
        int lineCount = lines.size();
        int characterCount = lines.stream()
                                .mapToInt(String::length)
                                .sum();
        return new FileStats(lineCount, 0, characterCount);
    }
}

