import java.util.*;

public class TreePathAnalyzer {
    public static class Node {
        int data;
        List<Node> children;

        public Node(int data) {
            this.data = data;
            this.children = new ArrayList<>();
        }

        public void addChild(Node child) {
            children.add(child);
        }

        @Override
        public String toString() {
            return String.valueOf(data);
        }
    }

    private List<Node> longestPath;
    private int maxLength;

    public List<Node> findLongestPath(Node root) {
        longestPath = new ArrayList<>();
        maxLength = 0;
        if (root == null) {
            return longestPath;
        }
        dfs(root);
        return longestPath;
    }

    private int dfs(Node node) {
        if (node == null) {
            return 0;
        }

        int max1 = 0;
        int max2 = 0;
        List<Node> longestChildPath = null;
        List<Node> secondLongestChildPath = null;

        for (Node child : node.children) {
            int childDepth = dfs(child);
            if (childDepth > max1) {
                max2 = max1;
                secondLongestChildPath = longestChildPath;
                max1 = childDepth;
                longestChildPath = getPath(child);
            } else if (childDepth > max2) {
                max2 = childDepth;
                secondLongestChildPath = getPath(child);
            }
        }

        int currentMax = max1 + max2 + 1;
        if (currentMax > maxLength) {
            maxLength = currentMax;
            updateLongestPath(node, longestChildPath, secondLongestChildPath, max1, max2);
        }

        return max1 + 1;
    }

    private List<Node> getPath(Node node) {
        List<Node> path = new ArrayList<>();
        while (node != null) {
            path.add(node);
            if (node.children.isEmpty()) {
                break;
            }
            Node next = null;
            int maxDepth = -1;
            for (Node child : node.children) {
                int depth = getDepth(child);
                if (depth > maxDepth) {
                    maxDepth = depth;
                    next = child;
                }
            }
            node = next;
        }
        return path;
    }

    private int getDepth(Node node) {
        if (node == null) {
            return 0;
        }
        int max = 0;
        for (Node child : node.children) {
            max = Math.max(max, getDepth(child));
        }
        return max + 1;
    }

    private void updateLongestPath(Node node, List<Node> path1, List<Node> path2, int len1, int len2) {
        List<Node> newPath = new ArrayList<>();

        if (path1 != null) {
            List<Node> firstPart = new ArrayList<>(path1.subList(path1.size() - len1, path1.size()));
            Collections.reverse(firstPart);
            newPath.addAll(firstPart);
        }

        newPath.add(node);

        if (path2 != null) {
            newPath.addAll(path2.subList(path2.size() - len2, path2.size()));
        }

        longestPath = newPath;
    }
}

