import java.util.concurrent.*;
import java.util.ArrayList;
import java.util.List;

public class AdvancedDotProductCalculator {
    public static int calculateDotProduct(int[] array1, int[] array2) {
        if (array1 == null) {
            throw new IllegalArgumentException("First array cannot be null");
        }
        if (array2 == null) {
            throw new IllegalArgumentException("Second array cannot be null");
        }
        if (array1.length != array2.length) {
            throw new IllegalArgumentException("Arrays must have the same length");
        }
        int dotProduct = 0;
        for (int i = 0; i < array1.length; i++) {
            dotProduct += array1[i] * array2[i];
        }
        return dotProduct;
    }

    public static int calculateDotProduct(int[] array1, int[] array2, int threadCount) {
        if (array1 == null) {
            throw new IllegalArgumentException("First array cannot be null");
        }
        if (array2 == null) {
            throw new IllegalArgumentException("Second array cannot be null");
        }
        if (array1.length != array2.length) {
            throw new IllegalArgumentException("Arrays must have the same length");
        }
        if (threadCount < 1) {
            throw new IllegalArgumentException("Thread count must be at least 1");
        }
        int n = array1.length;
        if (n == 0) {
            return 0;
        }
        threadCount = Math.min(threadCount, n);
        ExecutorService executor = Executors.newFixedThreadPool(threadCount);
        List<Callable<Integer>> tasks = new ArrayList<>();
        int chunkSize = (n + threadCount - 1) / threadCount;
        for (int i = 0; i < threadCount; i++) {
            int start = i * chunkSize;
            int end = Math.min(start + chunkSize, n);
            if (start >= n) {
                break;
            }
            tasks.add(() -> {
                int partialSum = 0;
                for (int j = start; j < end; j++) {
                    partialSum += array1[j] * array2[j];
                }
                return partialSum;
            });
        }
        int total = 0;
        try {
            List<Future<Integer>> futures = executor.invokeAll(tasks);
            for (Future<Integer> future : futures) {
                total += future.get();
            }
        } catch (InterruptedException | ExecutionException e) {
            Thread.currentThread().interrupt();
            throw new RuntimeException("Error during parallel computation", e);
        } finally {
            executor.shutdown();
        }
        return total;
    }
}

