import java.util.function.Supplier;

public class ConfigManager {
    private final Map<String, Object> beanMap = new HashMap<>();

    public void registerBean(String name, Supplier<Object> supplier) {
        if (beanMap.containsKey(name)) {
            throw new IllegalArgumentException("Bean with name '" + name + "' already registered");
        }
        beanMap.put(name, supplier.get());
