                if (uriMatches && methodMatches) {
                    return true;
                }
            }
        }
        return false;
    }

    private boolean matchesUri(String patternUri, String requestUri) {
        // Exact match
        if (patternUri.equals(requestUri)) {
            return true;
        }

        // Check for wildcard matching
        if (patternUri.contains("{*}")) {
            return matchesWithWildcard(patternUri, requestUri);
        }
        // Check for prefix matching (only if no wildcard present)
        else {
            return matchesWithPrefix(patternUri, requestUri);
        }
    }

    private boolean matchesWithWildcard(String patternUri, String requestUri) {
        String[] patternSegments = patternUri.split("/");
        String[] requestSegments = requestUri.split("/");

        if (patternSegments.length != requestSegments.length) {
            return false;
