                if (requestSegment.isEmpty() || !requestSegment.matches("[a-zA-Z0-9]+")) {
                    return false;
                }
            } else if (!patternSegment.equals(requestSegment)) {
                return false;
            }
        }

        return true;
    }

    private boolean matchesWithPrefix(String patternUri, String requestUri) {
        // Check if pattern is a prefix of the request URI and the next character is a segment boundary
        boolean isPrefix = requestUri.startsWith(patternUri);
        boolean hasSegmentBoundary = requestUri.length() > patternUri.length() && 
