import java.util.HashMap;
import java.util.Map;

class AuthTokenValidator {
    private Map<String, TokenInfo> tokenDatabase;
    private Map<String, User> userDatabase;

    public AuthTokenValidator() {
        // Initialize token database with token information including expiration and status
        tokenDatabase = new HashMap<>();
        long currentTime = System.currentTimeMillis();
        long oneHour = 3600 * 1000; // 1 hour in milliseconds

        // Add a valid token that expires in 1 hour
        tokenDatabase.put("example_token_123user127.0.0.1", 
            new TokenInfo(currentTime + oneHour, 1, "user1"));

        // Initialize user database
        userDatabase = new HashMap<>();
        userDatabase.put("user1", new User("user1", "John Doe"));
    }

    public Map<String, Object> validateToken(String token, String clientIp) {
        Map<String, Object> result = new HashMap<>();

        // Check if token is null or empty
        if (token == null || token.isEmpty()) {
            result.put("valid", false);
            result.put("message", "Token is empty");
            return result;
        }

        // Check if token contains 'user' substring
        if (!token.contains("user")) {
            result.put("valid", false);
            result.put("message", "Token format invalid");
            return result;
        }

        // Extract IP address from token and compare with clientIp
        int userIndex = token.indexOf("user");
        String extractedIp = token.substring(userIndex + 4);
        if (!extractedIp.equals(clientIp)) {
            result.put("valid", false);
            result.put("message", "IP address mismatch");
            return result;
        }

        // Check if token exists in the database
        TokenInfo tokenInfo = tokenDatabase.get(token);
        if (tokenInfo == null) {
            result.put("valid", false);
            result.put("message", "Token not found");
            return result;
        }

        // Check token expiration
        long currentTime = System.currentTimeMillis();
        if (tokenInfo.getExpiration() < currentTime) {
            result.put("valid", false);
            result.put("message", "Token expired");
            return result;
        }

        // Check token status
        if (tokenInfo.getStatus() != 1) {
            result.put("valid", false);
            result.put("message", "Token invalid");
            return result;
        }

        // Check if user exists
        User user = userDatabase.get(tokenInfo.getUserId());
        if (user == null) {
            result.put("valid", false);
            result.put("message", "User not found");
            return result;
        }

        result.put("valid", true);
        result.put("message", "Validation successful");
        result.put("user", user);
        return result;
    }

    // Inner class for token information
    class TokenInfo {
        private long expiration;
        private int status;
        private String userId;

        public TokenInfo(long expiration, int status, String userId) {
            this.expiration = expiration;
            this.status = status;
            this.userId = userId;
        }

        public long getExpiration() {
            return expiration;
        }

        public int getStatus() {
            return status;
        }

        public String getUserId() {
            return userId;
        }
    }

    // Inner class for user information
    class User {
        private String id;
        private String name;

        public User(String id, String name) {
            this.id = id;
            this.name = name;
        }

        public String getId() {
            return id;
        }

        public String getName() {
            return name;
        }

        @Override
        public String toString() {
            return "User{id='" + id + "', name='" + name + "'}";
        }
    }
}

