import java.util.concurrent.CompletableFuture;
import java.util.concurrent.CompletionException;
import java.util.concurrent.TimeUnit;
import java.util.function.Supplier;

class AsyncOperationManager {

    public <T> CompletableFuture<T> executeWithTimeoutAndRetry(
            Supplier<T> taskSupplier,
            long timeout,
            TimeUnit timeUnit,
            T fallbackValue,
            int maxRetries) {
        return executeWithRetry(taskSupplier, timeout, timeUnit, fallbackValue, maxRetries);
    }

    private <T> CompletableFuture<T> executeWithRetry(
            Supplier<T> taskSupplier,
            long timeout,
            TimeUnit timeUnit,
            T fallbackValue,
            int retriesLeft) {
        // Create the initial attempt with timeout
        CompletableFuture<T> attempt = CompletableFuture.supplyAsync(taskSupplier)
                .completeOnTimeout(fallbackValue, timeout, timeUnit);

        // Add retry logic for exceptions and timeouts
        return attempt.exceptionallyCompose(ex -> {
            if (retriesLeft > 0) {
                try {
                    Thread.sleep(500);
                    return executeWithRetry(taskSupplier, timeout, timeUnit, fallbackValue, retriesLeft - 1);
                } catch (InterruptedException e) {
                    CompletableFuture<T> interruptedFuture = new CompletableFuture<>();
                    interruptedFuture.completeExceptionally(e);
                    return interruptedFuture;
                }
            } else {
                return CompletableFuture.completedFuture(fallbackValue);
            }
        });
    }
}

