import java.util.concurrent.CompletableFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;
import java.util.function.Supplier;

class AsyncOperationManager {

    public <T> CompletableFuture<T> executeWithTimeoutAndRetry(
            Supplier<T> taskSupplier,
            long timeout,
            TimeUnit timeUnit,
            T fallbackValue,
            int maxRetries) {
        return executeWithRetry(taskSupplier, timeout, timeUnit, fallbackValue, maxRetries, false);
    }

    private <T> CompletableFuture<T> executeWithRetry(
            Supplier<T> taskSupplier,
            long timeout,
            TimeUnit timeUnit,
            T fallbackValue,
            int retriesLeft,
            boolean hasNonTimeoutException) {

        CompletableFuture<T> attempt = CompletableFuture.supplyAsync(taskSupplier)
                .orTimeout(timeout, timeUnit);

        return attempt.exceptionallyCompose(ex -> {
            boolean newHasNonTimeoutException = hasNonTimeoutException || 
                                              !(ex instanceof TimeoutException);

            if (retriesLeft > 0) {
                try {
                    Thread.sleep(500);
                    return executeWithRetry(taskSupplier, timeout, timeUnit, 
                                           fallbackValue, retriesLeft - 1, 
                                           newHasNonTimeoutException);
                } catch (InterruptedException e) {
                    CompletableFuture<T> interruptedFuture = new CompletableFuture<>();
                    interruptedFuture.completeExceptionally(e);
                    return interruptedFuture;
                }
            } else {
                if (newHasNonTimeoutException) {
                    CompletableFuture<T> failed = new CompletableFuture<>();
                    failed.completeExceptionally(ex);
                    return failed;
                } else {
                    return CompletableFuture.completedFuture(fallbackValue);
                }
            }
        });
    }
}

