import java.util.HashMap;
import java.util.Map;
import java.util.UUID;

class UserManager {
    private Map<String, User> userDatabase;
    private Map<String, String> activeSessions;

    public UserManager() {
        this.userDatabase = new HashMap<>();
        this.activeSessions = new HashMap<>();
    }

    public boolean registerUser(String username, String password, String email) {
        if (userDatabase.containsKey(username)) {
            return false; // Username already exists
        }
        userDatabase.put(username, new User(username, password, email));
        return true;
    }

    public String loginUser(String username, String password) {
        User user = userDatabase.get(username);
        if (user != null && user.getPassword().equals(password)) {
            String sessionToken = UUID.randomUUID().toString();
            activeSessions.put(sessionToken, username);
            return sessionToken;
        }
        return null;
    }

    public boolean logoutUser(String sessionToken) {
        return activeSessions.remove(sessionToken) != null;
    }
}

class User {
    private String username;
    private String password;
    private String email;

    public User(String username, String password, String email) {
        this.username = username;
        this.password = password;
        this.email = email;
    }

    public String getPassword() {
        return password;
    }
}

