        if (up && right && down && left && upLeft && upRight && downLeft && downRight) {
            return new TileConfiguration(4, 2);
        }

        // Check for full cross (all 4 cardinal directions)
        if (up && right && down && left) {
            // Check if all diagonals are present
            if (upLeft && upRight && downLeft && downRight) {
