    private final Map<String, List<Message>> messagesByDestination;
    private final Map<String, Integer> destinationCounts;
    private int totalMessages;

    public EnhancedMessageProcessor() {
        messagesByDestination = new HashMap<>();
        destinationCounts = new HashMap<>();
        totalMessages = 0;
    }

    public synchronized ProcessingResult postMessage(Message message, String destination) {
        // Initialize destination list if it doesn't exist
        messagesByDestination.computeIfAbsent(destination, k -> new ArrayList<>()).add(message);

        // Update destination count
        destinationCounts.put(destination, destinationCounts.getOrDefault(destination, 0) + 1);
        totalMessages++;

        // Create metadata with total message count
        Map<String, Integer> metadata = new HashMap<>();
        metadata.put("totalMessages", totalMessages);

        return new ProcessingResult(Status.SUCCESS, metadata);
    }

    public synchronized Message getMessage(String destination) {
        List<Message> messages = messagesByDestination.get(destination);
        if (messages == null || messages.isEmpty()) {
            return null;
        }
        // Return the latest message (last in the list)
        return messages.get(messages.size() - 1);
    }

