public class KeyValueStore<K, V> {
    private final ConcurrentHashMap<K, V> store;
    private final ConcurrentHashMap<K, Integer> accessCounts;

    public KeyValueStore() {
        this.store = new ConcurrentHashMap<>();
        this.accessCounts = new ConcurrentHashMap<>();
    }

    public void put(K key, V value) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }
        store.put(key, value);
    }

    public V get(K key) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }
        accessCounts.compute(key, (k, count) -> count == null ? 1 : count + 1);
        return store.get(key);
    }

    public int getAccessCount(K key) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }
        return accessCounts.getOrDefault(key, 0);
    }
}

