import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.stream.Collectors;

public class KeyValueStore<K, V> {
    private final ConcurrentHashMap<K, V> store;
    private final ConcurrentHashMap<K, Long> lastAccessTimes;
    private final ConcurrentHashMap<Class<?>, Integer> typeCounts;

    public KeyValueStore() {
        this.store = new ConcurrentHashMap<>();
        this.lastAccessTimes = new ConcurrentHashMap<>();
        this.typeCounts = new ConcurrentHashMap<>();
    }

    public void put(K key, V value) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }

        // Decrement count for previous value's type if it exists
        if (store.containsKey(key)) {
            V oldValue = store.get(key);
            if (oldValue != null) {
                typeCounts.compute(oldValue.getClass(), 
                    (cls, count) -> count == null || count == 1 ? null : count - 1);
            }
        }

        store.put(key, value);

        // Increment count for new value's type
        if (value != null) {
            typeCounts.compute(value.getClass(), 
                (cls, count) -> count == null ? 1 : count + 1);
        }
    }

    public void putAll(Map<? extends K, ? extends V> entries) {
        if (entries == null) {
            throw new IllegalArgumentException("Entries cannot be null");
        }
        entries.forEach(this::put);
    }

    public V get(K key) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }
        long currentTime = System.currentTimeMillis();
        lastAccessTimes.put(key, currentTime);
        return store.get(key);
    }

    public long getLastAccessTime(K key) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }
        return lastAccessTimes.getOrDefault(key, 0L);
    }

    public int getTypeCount(Class<?> type) {
        if (type == null) {
            throw new IllegalArgumentException("Type cannot be null");
        }
        return typeCounts.getOrDefault(type, 0);
    }

    public Set<K> findKeysByType(Class<?> type) {
        if (type == null) {
            throw new IllegalArgumentException("Type cannot be null");
        }
        return store.entrySet().stream()
                .filter(entry -> entry.getValue() != null && entry.getValue().getClass().equals(type))
                .map(Map.Entry::getKey)
                .collect(Collectors.toSet());
    }

    public void clear() {
        store.clear();
        lastAccessTimes.clear();
        typeCounts.clear();
    }

    public Statistics computeStatistics() {
        Statistics stats = new Statistics();

        // Total entries
        stats.totalEntries = store.size();

        // Key with maximum access time (most recently accessed)
        lastAccessTimes.entrySet().stream()
                .max(Map.Entry.comparingByValue())
                .ifPresent(entry -> stats.keyWithMaxAccess = entry.getKey());

        // Type distribution (copy to prevent external modification)
        stats.typeDistribution = new HashMap<>(typeCounts);

        // Estimated memory usage (rough approximation)
        stats.estimatedMemoryUsage = store.size() * 100L; // Rough estimate of 100 bytes per entry

        return stats;
    }

    public static class Statistics {
        public int totalEntries;
        public K keyWithMaxAccess;
        public Map<Class<?>, Integer> typeDistribution;
        public long estimatedMemoryUsage;

        @Override
        public String toString() {
            return String.format(
                "Statistics{totalEntries=%d, keyWithMaxAccess=%s, typeDistribution=%s, estimatedMemoryUsage=%d}",
                totalEntries, keyWithMaxAccess, typeDistribution, estimatedMemoryUsage
            );
        }
    }
}

