import java.util.List;
import java.util.Map;

public class ObjectInspector {

    public Map<String, Object> inspectObject(Object object, int maxDepth) {
        Map<String, Object> result = new HashMap<>();

        if (object == null) {
            result.put("value", null);
            return result;
        }

        Class<?> clazz = object.getClass();

        if (clazz.isArray()) {
            Class<?> componentType = clazz.getComponentType();
            result.put("type", componentType.getSimpleName() + "[]");

            if (maxDepth <= 0) {
                result.put("value", "[...]");
            } else {
                List<Map<String, Object>> arrayElements = new ArrayList<>();
                int length = Array.getLength(object);
                for (int i = 0; i < length; i++) {
                    Object element = Array.get(object, i);
                    arrayElements.add(inspectObject(element, maxDepth - 1));
                }
                result.put("value", arrayElements);
            }
        } else if (isSimpleType(object)) {
            result.put("type", clazz.getSimpleName());
            result.put("value", object);
        } else {
            result.put("type", clazz.getSimpleName());

            if (maxDepth <= 0) {
                result.put("value", "{...}");
            } else {
                Map<String, Map<String, Object>> fieldsMap = new HashMap<>();
                Class<?> currentClass = clazz;

                while (currentClass != null && currentClass != Object.class) {
                    Field[] fields = currentClass.getDeclaredFields();
                    for (Field field : fields) {
                        if (!Modifier.isStatic(field.getModifiers())) {
                            field.setAccessible(true);
                            try {
                                Object fieldValue = field.get(object);
                                fieldsMap.put(field.getName(), inspectObject(fieldValue, maxDepth - 1));
                            } catch (IllegalAccessException e) {
                                Map<String, Object> errorResult = new HashMap<>();
                                errorResult.put("type", "ERROR");
                                errorResult.put("value", "Unable to access field: " + e.getMessage());
                                fieldsMap.put(field.getName(), errorResult);
                            }
                        }
                    }
                    currentClass = currentClass.getSuperclass();
                }

                result.put("fields", fieldsMap);
            }
        }

        return result;
    }

    public Map<String, Object> inspectObject(Object object) {
        return inspectObject(object, 5);
    }

    private boolean isSimpleType(Object object) {
        if (object == null) {
            return false;
        }
        Class<?> clazz = object.getClass();
        return clazz == String.class || 
               Number.class.isAssignableFrom(clazz) || 
               clazz == Boolean.class || 
               clazz == Character.class;
    }
