        if (grid == null || grid.length == 0 || grid[0].length == 0) {
            throw new IllegalArgumentException("Grid cannot be null or empty");
        }

        if (xOffset < 0 || yOffset < 0) {
            throw new IllegalArgumentException("Offset coordinates must be non-negative");
        }

        if ("glider".equals(patternName)) {
            Coordinate[] gliderPattern = {
                new Coordinate(0, 0),
                new Coordinate(1, 0),
                new Coordinate(2, 0),
                new Coordinate(2, 1),
                new Coordinate(1, 2)
