class ClientManager {
    private final List<ClientTO> clients = new ArrayList<>();
    private final AtomicLong idCounter = new AtomicLong(1L);

    private boolean hasAdminPrivileges() {
        return false;
    }

    public List<ClientTO> findAllClients(String filter, boolean requireAdmin) {
        if (requireAdmin && !hasAdminPrivileges()) {
            throw new SecurityException("Admin privileges required");
        }

        if (filter == null || filter.trim().isEmpty()) {
            return new ArrayList<>(clients);
        }

        String lowerCaseFilter = filter.toLowerCase();
        List<ClientTO> filteredClients = new ArrayList<>();
        for (ClientTO client : clients) {
            if ((client.getFirstName() != null && client.getFirstName().toLowerCase().contains(lowerCaseFilter)) ||
                (client.getLastName() != null && client.getLastName().toLowerCase().contains(lowerCaseFilter)) ||
                (client.getEmail() != null && client.getEmail().toLowerCase().contains(lowerCaseFilter))) {
                filteredClients.add(client);
            }
        }
        return filteredClients;
    }

    public List<ClientTO> findClientsByName(String name, boolean requireAdmin) {
        if (requireAdmin && !hasAdminPrivileges()) {
            throw new SecurityException("Admin privileges required");
        }
        if (name == null || name.trim().isEmpty()) {
            throw new IllegalArgumentException("Name cannot be null or empty");
        }

        String lowerCaseName = name.toLowerCase();
        List<ClientTO> matchingClients = new ArrayList<>();
        for (ClientTO client : clients) {
            if ((client.getFirstName() != null && client.getFirstName().toLowerCase().contains(lowerCaseName)) ||
                (client.getLastName() != null && client.getLastName().toLowerCase().contains(lowerCaseName))) {
                matchingClients.add(client);
            }
        }
        return matchingClients;
    }

    public List<ClientTO> findAllClients(boolean requireAdmin) {
        return findAllClients(null, requireAdmin);
    }

    public ClientTO findClient(Long id, boolean requireAdmin) {
        if (requireAdmin && !hasAdminPrivileges()) {
            throw new SecurityException("Admin privileges required");
        }
        if (id == null) {
            throw new IllegalArgumentException("ID cannot be null");
        }
        for (ClientTO client : clients) {
            if (id.equals(client.getId())) {
                return client;
            }
        }
        return null;
    }

    public boolean deleteClient(Long id, boolean requireAdmin) {
        if (requireAdmin && !hasAdminPrivileges()) {
            throw new SecurityException("Admin privileges required");
        }
        if (id == null) {
            throw new IllegalArgumentException("ID cannot be null");
        }
        return clients.removeIf(client -> id.equals(client.getId()));
    }

    public ClientTO createClient(ClientTO client) {
        if (client == null) {
            throw new IllegalArgumentException("Client cannot be null");
        }
        if (client.getId() != null) {
            throw new IllegalArgumentException("Client ID must be null for new client");
        }
        validateClientAttributes(client);

        client.setId(idCounter.getAndIncrement());
        clients.add(client);
        return client;
    }

    public ClientTO updateClient(ClientTO client) {
        if (client == null) {
            throw new IllegalArgumentException("Client cannot be null");
        }
        if (client.getId() == null) {
            throw new IllegalArgumentException("Client ID cannot be null for update");
        }

        ClientTO existingClient = findClient(client.getId(), false);
        if (existingClient == null) {
            throw new IllegalArgumentException("Client with ID " + client.getId() + " does not exist");
        }

        validateClientAttributes(client);

        existingClient.setFirstName(client.getFirstName());
        existingClient.setLastName(client.getLastName());
        existingClient.setEmail(client.getEmail());
        existingClient.setPhone(client.getPhone());

        return existingClient;
    }

    private void validateClientAttributes(ClientTO client) {
        if (client.getFirstName() == null || client.getFirstName().trim().isEmpty()) {
            throw new IllegalArgumentException("First name cannot be null or empty");
        }
        if (client.getLastName() == null || client.getLastName().trim().isEmpty()) {
            throw new IllegalArgumentException("Last name cannot be null or empty");
        }
        if (client.getEmail() == null || client.getEmail().trim().isEmpty()) {
            throw new IllegalArgumentException("Email cannot be null or empty");
        }
        if (!client.getEmail().contains("@")) {
            throw new IllegalArgumentException("Email must contain '@'");
        }
    }
}
