        return message;
    }
}

public class AuthenticationService {
    private final Map<String, String> userCredentials;

    public AuthenticationService() {
        userCredentials = new HashMap<>();
    }

    public static class PasswordValidator {
        public static ValidationResult validate(String password) {
            if (password == null) {
                return new ValidationResult(false, "Password cannot be null");
            }

            if (password.length() < 8) {
                return new ValidationResult(false, "Password must be at least 8 characters long");
            }

            if (!password.matches(".*[A-Z].*")) {
                return new ValidationResult(false, "Password must contain at least one uppercase letter");
            }

            if (!password.matches(".*[a-z].*")) {
                return new ValidationResult(false, "Password must contain at least one lowercase letter");
            }

            if (!password.matches(".*\\d.*")) {
                return new ValidationResult(false, "Password must contain at least one digit");
            }

            if (!password.matches(".*[!@#$%^&*()\\-_=+\\\\|\\[\\]{};:'\",.<>/?].*")) {
                return new ValidationResult(false, "Password must contain at least one special character");
            }

            return new ValidationResult(true, "Password is valid");
        }
    }

    public static class ValidationResult {
        private final boolean valid;
        private final String message;

        public ValidationResult(boolean valid, String message) {
            this.valid = valid;
            this.message = message;
        }

        public boolean isValid() {
            return valid;
        }

        public String getMessage() {
            return message;
        }
    }

    public AuthenticationResult authenticate(String username, String password) {
        if (username == null || password == null) {
            return new AuthenticationResult(false, "Username and password cannot be null");
        }

        String storedPassword = userCredentials.get(username);
        if (storedPassword == null) {
            return new AuthenticationResult(false, "User not found");
        }

        if (storedPassword.equals(password)) {
            return new AuthenticationResult(true, "Authentication successful");
        } else {
            return new AuthenticationResult(false, "Invalid password");
        }
    }

    public RegistrationResult registerUser(String username, String password) {
        if (username == null || password == null) {
            return new RegistrationResult(false, "Username and password cannot be null");
        }
        if (username.isEmpty() || password.isEmpty()) {
            return new RegistrationResult(false, "Username and password cannot be empty");
        }

        ValidationResult validationResult = PasswordValidator.validate(password);
        if (!validationResult.isValid()) {
            return new RegistrationResult(false, validationResult.getMessage());
        }

        if (userCredentials.containsKey(username)) {
            return new RegistrationResult(false, "Username already exists");
