import java.util.List;
import java.util.ArrayList;
import java.util.Comparator;

public class RedditFeedAnalyzer {
    public String analyzeAndFormatFeed(List<RedditFeedItem> feedItems, int minScore) {
        if (feedItems == null || feedItems.isEmpty()) {
            return "No feed items to analyze";
        }

        List<RedditFeedItem> validItems = new ArrayList<>();
        double totalScore = 0;
        double totalComments = 0;

        for (RedditFeedItem item : feedItems) {
            try {
                int score = item.getScore();
                int numComments = item.getNumComments();

                if (score >= minScore) {
                    validItems.add(item);
                    totalScore += score;
                    totalComments += numComments;
                }
            } catch (NumberFormatException e) {
                // Skip items with invalid score or numComments
                continue;
            }
        }

        int count = validItems.size();
        double avgScore = count > 0 ? totalScore / count : 0.0;
        double avgComments = count > 0 ? totalComments / count : 0.0;

        // Sort valid items by score in descending order
        validItems.sort(Comparator.comparingInt(RedditFeedItem::getScore).reversed());

        // Build the summary string
        StringBuilder summary = new StringBuilder();
        summary.append(String.format("Feed Analysis Summary:\nTotal items: %d\nAverage score: %.2f\nAverage comments: %.2f\n", 
                            count, avgScore, avgComments));

        // Add top 3 items section
        summary.append("Top 3 items by score:\n");
        for (int i = 0; i < Math.min(3, validItems.size()); i++) {
            RedditFeedItem item = validItems.get(i);
            summary.append(String.format("%d. %s (Score: %d, Comments: %d)\n", 
                i + 1, item.getTitle(), item.getScore(), item.getNumComments()));
        }

        return summary.toString();
    }
}

