import java.text.ParseException;
import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.HashMap;
import java.util.Map;

class TimeDifferenceCalculator {
    private static final String DEFAULT_DATETIME_PATTERN = "yyyy-MM-dd HH:mm:ss";
    private static final long SECOND_MS = 1000;
    private static final long MINUTE_MS = 60 * SECOND_MS;
    private static final long HOUR_MS = 60 * MINUTE_MS;
    private static final long DAY_MS = 24 * HOUR_MS;
    private static final long WEEK_MS = 7 * DAY_MS;

    public static Map<String, Object> calculateDetailedTimeDifference(String earlierTime, String laterTime) 
            throws ParseException {
        SimpleDateFormat sdf = new SimpleDateFormat(DEFAULT_DATETIME_PATTERN);
        Date earlierDate = sdf.parse(earlierTime);
        Date laterDate = sdf.parse(laterTime);

        long diffMillis = laterDate.getTime() - earlierDate.getTime();

        Map<String, Object> result = new HashMap<>();
        result.put("seconds", diffMillis / SECOND_MS);
        result.put("minutes", diffMillis / MINUTE_MS);
        result.put("hours", diffMillis / HOUR_MS);
        result.put("days", diffMillis / DAY_MS);
        result.put("weeks", diffMillis / WEEK_MS);
        result.put("humanReadable", buildHumanReadableString(diffMillis));

        return result;
    }

    private static String buildHumanReadableString(long diffMillis) {
        long absDiff = Math.abs(diffMillis);
        long weeks = absDiff / WEEK_MS;
        absDiff %= WEEK_MS;
        long days = absDiff / DAY_MS;
        absDiff %= DAY_MS;
        long hours = absDiff / HOUR_MS;
        absDiff %= HOUR_MS;
        long minutes = absDiff / MINUTE_MS;
        absDiff %= MINUTE_MS;
        long seconds = absDiff / SECOND_MS;

        StringBuilder sb = new StringBuilder();
        if (weeks > 0) {
            sb.append(weeks).append(weeks == 1 ? " week" : " weeks");
        }
        if (days > 0) {
            addCommaIfNeeded(sb);
            sb.append(days).append(days == 1 ? " day" : " days");
        }
        if (hours > 0) {
            addCommaIfNeeded(sb);
            sb.append(hours).append(hours == 1 ? " hour" : " hours");
        }
        if (minutes > 0) {
            addCommaIfNeeded(sb);
            sb.append(minutes).append(minutes == 1 ? " minute" : " minutes");
        }
        if (seconds > 0 || sb.length() == 0) {
            addCommaIfNeeded(sb);
            sb.append(seconds).append(seconds == 1 ? " second" : " seconds");
        }

        return sb.toString();
    }

    private static void addCommaIfNeeded(StringBuilder sb) {
        if (sb.length() > 0) {
            sb.append(", ");
        }
    }
}

