import java.util.ArrayList;

public class EnhancedBinaryHeap {
    private ArrayList<Integer> heap;
    private boolean isMinHeap;

    public EnhancedBinaryHeap() {
        this(true); // Default to min-heap
    }

    public EnhancedBinaryHeap(boolean isMinHeap) {
        this.heap = new ArrayList<>();
        this.isMinHeap = isMinHeap;
    }

    public void insert(int value) {
        heap.add(value);
        heapifyUp(heap.size() - 1);
    }

    public int deleteRoot() {
        if (isEmpty()) {
            throw new IllegalStateException("Heap is empty");
        }
        int root = heap.get(0);
        int lastElement = heap.remove(heap.size() - 1);
        if (!isEmpty()) {
            heap.set(0, lastElement);
            heapifyDown(0);
        }
        return root;
    }

    public int peekRoot() {
        if (isEmpty()) {
            throw new IllegalStateException("Heap is empty");
        }
        return heap.get(0);
    }

    public boolean isEmpty() {
        return heap.isEmpty();
    }

    public int size() {
        return heap.size();
    }

    public void makeEmpty() {
        heap.clear();
    }

    private void heapifyUp(int index) {
        while (index > 0) {
            int parentIndex = (index - 1) / 2;
            if (compare(heap.get(index), heap.get(parentIndex))) {
                swap(index, parentIndex);
                index = parentIndex;
            } else {
                break;
            }
        }
    }

    private void heapifyDown(int index) {
        int size = heap.size();
        while (index < size) {
            int leftChild = 2 * index + 1;
            int rightChild = 2 * index + 2;
            int target = index;

            if (leftChild < size && compare(heap.get(leftChild), heap.get(target))) {
                target = leftChild;
            }
            if (rightChild < size && compare(heap.get(rightChild), heap.get(target))) {
                target = rightChild;
            }
            if (target == index) break;
            swap(index, target);
            index = target;
        }
    }

    private boolean compare(int a, int b) {
        if (isMinHeap) {
            return a < b;
        } else {
            return a > b;
        }
    }

    private void swap(int i, int j) {
        int temp = heap.get(i);
        heap.set(i, heap.get(j));
        heap.set(j, temp);
    }
}

