public class EnhancedBinaryHeap {
    private ArrayList<Integer> heap;
    private ArrayList<Integer> vertex1List;
    private ArrayList<Integer> vertex2List;
    private boolean isMinHeap;

    public EnhancedBinaryHeap() {
        this(true);
    }

    public EnhancedBinaryHeap(boolean isMinHeap) {
        this.heap = new ArrayList<>();
        this.vertex1List = new ArrayList<>();
        this.vertex2List = new ArrayList<>();
        this.isMinHeap = isMinHeap;
    }

    public void insert(int value, int v1, int v2) {
        heap.add(value);
        vertex1List.add(v1);
        vertex2List.add(v2);
        heapifyUp(heap.size() - 1);
    }

    public int deleteRoot() {
        if (isEmpty()) {
            throw new IllegalStateException("Heap is empty");
        }
        int root = heap.get(0);
        swap(0, heap.size() - 1);
        heap.remove(heap.size() - 1);
        vertex1List.remove(vertex1List.size() - 1);
        vertex2List.remove(vertex2List.size() - 1);
        if (!isEmpty()) {
            heapifyDown(0);
        }
        return root;
    }

    public int peekRoot() {
        if (isEmpty()) {
            throw new IllegalStateException("Heap is empty");
        }
        return heap.get(0);
    }

    public int[] peekRootVertices() {
        if (isEmpty()) {
            throw new IllegalStateException("Heap is empty");
        }
        return new int[]{vertex1List.get(0), vertex2List.get(0)};
    }

    public boolean isEmpty() {
        return heap.isEmpty();
    }

    public int size() {
        return heap.size();
    }

    public void makeEmpty() {
        heap.clear();
        vertex1List.clear();
        vertex2List.clear();
    }

    private void heapifyUp(int index) {
