import java.util.HashMap;
import java.util.Map;

public class ServerApprovalHandler {
    private String serverName;
    private String serverIp;
    private String realmId;
    private String imageId;
    private String hardwareProfileId;
    private Map<String, String> approvalStatus;

    public ServerApprovalHandler(String serverName, String serverIp, String realmId, String imageId, String hardwareProfileId) {
        this.serverName = serverName;
        this.serverIp = serverIp;
        this.realmId = realmId;
        this.imageId = imageId;
        this.hardwareProfileId = hardwareProfileId;
        this.approvalStatus = new HashMap<>();
    }

    public Map<String, Boolean> validateConfiguration() {
        Map<String, Boolean> validationResults = new HashMap<>();
        validationResults.put("serverName", serverName != null && !serverName.trim().isEmpty());
        validationResults.put("serverIp", serverIp != null && !serverIp.trim().isEmpty());
        validationResults.put("realmId", realmId != null && !realmId.trim().isEmpty());
        validationResults.put("imageId", imageId != null && !imageId.trim().isEmpty());
        validationResults.put("hardwareProfileId", hardwareProfileId != null && !hardwareProfileId.trim().isEmpty());
        return validationResults;
    }

    public Map<String, Object> processApproval() {
        Map<String, Boolean> validationResults = validateConfiguration();
        boolean allValid = validationResults.values().stream().allMatch(Boolean::booleanValue);

        Map<String, String> statusUpdate = new HashMap<>();
        statusUpdate.put("configuration", allValid ? "APPROVED" : "REJECTED");
        approvalStatus.putAll(statusUpdate);

        Map<String, Object> result = new HashMap<>();
        result.put("approvalStatus", approvalStatus);
        result.put("message", allValid ? "Configuration approved successfully" : "Configuration validation failed");
        result.put("validationResults", validationResults);

        return result;
    }
}

