import java.util.regex.Pattern;

public class ServerApprovalHandler {
    private String serverName;
    private String serverIp;
    private String realmId;
    private String imageId;
    private String hardwareProfileId;
    private Map<String, String> approvalStatus;

    public ServerApprovalHandler(String serverName, String serverIp, String realmId, String imageId, String hardwareProfileId) {
        this.serverName = serverName;
        this.serverIp = serverIp;
        this.realmId = realmId;
        this.imageId = imageId;
        this.hardwareProfileId = hardwareProfileId;
        this.approvalStatus = new HashMap<>();
    }

    private String validateServerName() {
        if (serverName == null || serverName.trim().isEmpty()) {
            return "Server name cannot be null or empty";
        }
        if (serverName.length() > 64) {
            return "Server name cannot exceed 64 characters";
        }
        return "Valid";
    }

    private String validateIpAddress() {
        if (serverIp == null || serverIp.trim().isEmpty()) {
            return "IP address cannot be null or empty";
        }

        String ipv4Pattern = "^((25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$";
        if (!Pattern.matches(ipv4Pattern, serverIp)) {
            return "Invalid IPv4 address format";
        }
        return "Valid";
    }

    private String validateRealmId() {
        if (realmId == null || realmId.trim().isEmpty()) {
            return "Realm ID cannot be null or empty";
        }

        String realmPattern = "^[a-zA-Z0-9-]{1,36}$";
        if (!Pattern.matches(realmPattern, realmId)) {
            return "Realm ID must be 1-36 characters long and contain only alphanumeric characters and hyphens";
        }
        return "Valid";
    }

    public Map<String, String> validateConfiguration() {
        Map<String, String> validationResults = new HashMap<>();
        validationResults.put("serverName", validateServerName());
        validationResults.put("serverIp", validateIpAddress());
