import java.nio.file.*;
import java.io.IOException;
import java.util.List;

public class FileHandler {
    public static String handleFileOperation(String operationType, List<Path> files, String targetDirectory) {
        if ("upload".equals(operationType)) {
            try {
                Path targetDir = Paths.get(targetDirectory);
                Files.createDirectories(targetDir);

                int uploadedCount = 0;
                for (Path file : files) {
                    Path targetPath = targetDir.resolve(file.getFileName());
                    Files.copy(file, targetPath, StandardCopyOption.REPLACE_EXISTING);
                    uploadedCount++;
                }
                return "Successfully uploaded " + uploadedCount + " files";
            } catch (IOException e) {
                return "Error during file operation: " + e.getMessage();
            }
        }
        return "Operation not supported";
    }
}

