import java.util.*;

class EggDropSolver {
    public static int solveEggDrop(int k, int n) {
        if (k <= 0 || n <= 0) {
            throw new IllegalArgumentException("Number of eggs and floors must be positive.");
        }
        int[] dp = new int[k + 1];
        int attempts = 0;
        while (dp[k] < n) {
            attempts++;
            for (int i = k; i >= 1; i--) {
                dp[i] += dp[i - 1] + 1;
            }
        }
        return attempts;
    }

    public static int solveEggDropMath(int k, int n) {
        if (k <= 0 || n <= 0) {
            throw new IllegalArgumentException("Number of eggs and floors must be positive.");
        }
        int lo = 1, hi = n;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (binomialSum(mid, k, n) < n) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }

    private static long binomialSum(int x, int k, int n) {
        long sum = 0;
        long term = 1;
        for (int i = 1; i <= k; i++) {
            term = term * (x - i + 1) / i;
            sum += term;
            if (sum > n) break;
        }
        return sum;
    }

    public static String compareMethods(int k, int n) {
        long startTime = System.nanoTime();
        int dpResult = solveEggDrop(k, n);
        long dpTime = System.nanoTime() - startTime;

        startTime = System.nanoTime();
        int mathResult = solveEggDropMath(k, n);
        long mathTime = System.nanoTime() - startTime;

        return String.format("DP Result: %d, Time: %d ns%nMath Result: %d, Time: %d ns", 
                           dpResult, dpTime, mathResult, mathTime);
    }
}

