import java.util.*;
import java.util.concurrent.*;

class EggDropSolver {

    public static class EggDropResult {
        public final int dpResult;
        public final long dpTime;
        public final int mathResult;
        public final long mathTime;
        public final int memoResult;
        public final long memoTime;

        public EggDropResult(int dpResult, long dpTime, int mathResult, long mathTime, int memoResult, long memoTime) {
            this.dpResult = dpResult;
            this.dpTime = dpTime;
            this.mathResult = mathResult;
            this.mathTime = mathTime;
            this.memoResult = memoResult;
            this.memoTime = memoTime;
        }

        @Override
        public String toString() {
            return String.format(
                "DP Result: %d (%d ns)\nMath Result: %d (%d ns)\nMemo Result: %d (%d ns)",
                dpResult, dpTime, mathResult, mathTime, memoResult, memoTime
            );
        }
    }

    public static int solveEggDrop(int k, int n) {
        if (k <= 0 || n <= 0) {
            throw new IllegalArgumentException("Number of eggs and floors must be positive.");
        }
        int[] dp = new int[k + 1];
        int attempts = 0;
        while (dp[k] < n) {
            attempts++;
            for (int i = k; i >= 1; i--) {
                dp[i] += dp[i - 1] + 1;
            }
        }
        return attempts;
    }

    public static int solveEggDropMath(int k, int n) {
        if (k <= 0 || n <= 0) {
            throw new IllegalArgumentException("Number of eggs and floors must be positive.");
        }
        int lo = 1, hi = n;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (binomialSum(mid, k, n) < n) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }

    private static long binomialSum(int x, int k, int n) {
        long sum = 0;
        long term = 1;
        for (int i = 1; i <= k; i++) {
            term = term * (x - i + 1) / i;
            sum += term;
            if (sum > n) break;
        }
        return sum;
    }

    public static int solveEggDropMemo(int k, int n) {
        if (k <= 0 || n <= 0) {
            throw new IllegalArgumentException("Number of eggs and floors must be positive.");
        }
        int[][] memo = new int[k + 1][n + 1];
        for (int[] row : memo) {
            Arrays.fill(row, -1);
        }
        return helper(k, n, memo);
    }

    private static int helper(int eggs, int floors, int[][] memo) {
        if (floors == 0) return 0;
        if (eggs == 1) return floors;
        if (memo[eggs][floors] != -1) return memo[eggs][floors];

        int left = 1, right = floors;
        int result = Integer.MAX_VALUE;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            int broken = helper(eggs - 1, mid - 1, memo);
            int notBroken = helper(eggs, floors - mid, memo);
            int worst = Math.max(broken, notBroken) + 1;
            if (broken < notBroken) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
            result = Math.min(result, worst);
        }
        memo[eggs][floors] = result;
        return result;
    }

    public static EggDropResult compareAllMethods(int k, int n) {
        long startTime = System.nanoTime();
        int dpResult = solveEggDrop(k, n);
        long dpTime = System.nanoTime() - startTime;

        startTime = System.nanoTime();
        int mathResult = solveEggDropMath(k, n);
        long mathTime = System.nanoTime() - startTime;

        startTime = System.nanoTime();
        int memoResult = solveEggDropMemo(k, n);
        long memoTime = System.nanoTime() - startTime;

        return new EggDropResult(dpResult, dpTime, mathResult, mathTime, memoResult, memoTime);
    }
}

