import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.Map;

public class AlertingService {
    private ConcurrentMap<String, AtomicInteger> alertCounts;
    private ConcurrentMap<String, String> lastAlertMessages;
    private ConcurrentMap<String, ConcurrentMap<String, AlertListener>> listeners;

    public AlertingService() {
        alertCounts = new ConcurrentHashMap<>();
        lastAlertMessages = new ConcurrentHashMap<>();
        listeners = new ConcurrentHashMap<>();
    }

    public void triggerAlert(String level, String message) {
        // Atomically update alert count
        alertCounts.compute(level, (k, v) -> {
            if (v == null) {
                return new AtomicInteger(1);
            } else {
                v.incrementAndGet();
                return v;
            }
        });

        // Update last alert message (ConcurrentHashMap.put is thread-safe)
        lastAlertMessages.put(level, message);

        // Notify listeners for this alert level
        ConcurrentMap<String, AlertListener> levelListeners = listeners.get(level);
        if (levelListeners != null) {
            for (AlertListener listener : levelListeners.values()) {
                listener.onAlert(message);
            }
        }
    }

    public int getAlertCount(String level) {
        AtomicInteger count = alertCounts.get(level);
        return count != null ? count.get() : 0;
    }

    public String getLastAlertMessage(String level) {
        return lastAlertMessages.get(level);
    }

    public void resetStatistics() {
        alertCounts.clear();
        lastAlertMessages.clear();
    }

    public void addAlertListener(String listenerId, String level, AlertListener callback) {
        listeners.computeIfAbsent(level, k -> new ConcurrentHashMap<>())
                .put(listenerId, callback);
    }

    public void removeAlertListener(String listenerId, String level) {
        ConcurrentMap<String, AlertListener> levelListeners = listeners.get(level);
        if (levelListeners != null) {
            levelListeners.remove(listenerId);
            // Clean up empty level entries
            if (levelListeners.isEmpty()) {
                listeners.remove(level);
            }
        }
    }

    public interface AlertListener {
        void onAlert(String message);
    }
}

