import java.util.Comparator;
import java.util.Arrays;

class EnhancedMergeSort {

    public Integer[] sortIntegers(Integer[] array) {
        return sort(array, Comparator.naturalOrder(), true);
    }

    public <T> T[] sort(T[] array, Comparator<? super T> comparator, boolean ascending) {
        if (array == null) {
            throw new IllegalArgumentException("Array must not be null");
        }
        if (comparator == null) {
            throw new IllegalArgumentException("Comparator must not be null");
        }
        if (array.length <= 1) {
            return array;
        }

        // Create a comparator that handles both ascending and descending order
        Comparator<? super T> actualComparator = ascending ? 
            comparator : 
            comparator.reversed();

        return mergeSort(array, 0, array.length - 1, actualComparator);
    }

    private <T> T[] mergeSort(T[] array, int left, int right, Comparator<? super T> comparator) {
        if (left < right) {
            int mid = left + (right - left) / 2;
            mergeSort(array, left, mid, comparator);
            mergeSort(array, mid + 1, right, comparator);
            merge(array, left, mid, right, comparator);
        }
        return array;
    }

    private <T> void merge(T[] array, int left, int mid, int right, Comparator<? super T> comparator) {
        int n1 = mid - left + 1;
        int n2 = right - mid;

        // Create temporary arrays
        T[] leftArray = Arrays.copyOfRange(array, left, mid + 1);
        T[] rightArray = Arrays.copyOfRange(array, mid + 1, right + 1);

        // Merge the temporary arrays
        int i = 0, j = 0, k = left;
        while (i < n1 && j < n2) {
            if (comparator.compare(leftArray[i], rightArray[j]) <= 0) {
                array[k] = leftArray[i];
                i++;
            } else {
                array[k] = rightArray[j];
                j++;
            }
            k++;
        }

        // Copy remaining elements
        while (i < n1) {
            array[k] = leftArray[i];
            i++;
            k++;
        }

        while (j < n2) {
            array[k] = rightArray[j];
            j++;
            k++;
        }
    }
}

