    private static <T> void mergeArrays(T[] leftArray, T[] rightArray, T[] targetArray, 
                                       Comparator<? super T> comparator, boolean ascending) {
        int i = 0, j = 0, k = 0;

        while (i < leftArray.length && j < rightArray.length) {
