class DataStructureAnalyzer {
    public static Map<String, Object> analyzeDataStructure(Object data) {
        if (data == null) {
            throw new IllegalArgumentException("Input data cannot be null");
        }

        Map<String, Object> result = new LinkedHashMap<>();
        result.put("containsBinary", false);
        result.put("maxDepth", 0);
        result.put("totalElements", 0);
        Map<String, Integer> typeCounts = new LinkedHashMap<>();
        result.put("typeCounts", typeCounts);

        analyzeRecursive(data, result, typeCounts, 1);

        return result;
    }

    private static void analyzeRecursive(Object data, Map<String, Object> result, 
                                       Map<String, Integer> typeCounts, int currentDepth) {
        // Update max depth
        int currentMaxDepth = (Integer) result.get("maxDepth");
        if (currentDepth > currentMaxDepth) {
            result.put("maxDepth", currentDepth);
        }

        // Update total elements
        int totalElements = (Integer) result.get("totalElements");
        result.put("totalElements", totalElements + 1);

        // Update type counts
        String type = data.getClass().getSimpleName();
        typeCounts.put(type, typeCounts.getOrDefault(type, 0) + 1);

        // Check for binary data
        if (data instanceof byte[]) {
            result.put("containsBinary", true);
        }

        // Handle arrays (excluding byte[])
        if (data.getClass().isArray() && !(data instanceof byte[])) {
            int length = Array.getLength(data);
            for (int i = 0; i < length; i++) {
                Object element = Array.get(data, i);
                analyzeRecursive(element, result, typeCounts, currentDepth + 1);
            }
        }
        // Handle collections
        else if (data instanceof Collection) {
            Collection<?> collection = (Collection<?>) data;
            for (Object element : collection) {
                analyzeRecursive(element, result, typeCounts, currentDepth + 1);
            }
        }
        // Handle maps
        else if (data instanceof Map) {
            Map<?, ?> map = (Map<?, ?>) data;
            for (Map.Entry<?, ?> entry : map.entrySet()) {
                analyzeRecursive(entry.getKey(), result, typeCounts, currentDepth + 1);
                analyzeRecursive(entry.getValue(), result, typeCounts, currentDepth + 1);
            }
        }
    }
}

