        for (String key : typeKeys) {
            typeCounts.put(key, 0);
        }
        result.put("typeCounts", typeCounts);

        analyzeRecursive(data, result, typeCounts, 1);

        return result;
    }

    private static void analyzeRecursive(Object data, Map<String, Object> result, 
                                       Map<String, Integer> typeCounts, int currentDepth) {
        // Update max depth
        int currentMaxDepth = (Integer) result.get("maxDepth");
        if (currentDepth > currentMaxDepth) {
            result.put("maxDepth", currentDepth);
        }

        // Update total elements
        int totalElements = (Integer) result.get("totalElements");
        result.put("totalElements", totalElements + 1);

        // Determine and update type counts
        String type;
        if (data instanceof JSONObject) {
            type = "JSONObject";
        } else if (data instanceof JSONArray) {
            type = "JSONArray";
        } else if (data instanceof String) {
            type = "String";
        } else if (data instanceof Number) {
            type = "Number";
        } else if (data instanceof Boolean) {
            type = "Boolean";
        } else if (data instanceof byte[]) {
            type = "byte[]";
            // Set containsBinary to true for byte arrays
            result.put("containsBinary", true);
        } else {
            type = "Other";
        }

        typeCounts.put(type, typeCounts.get(type) + 1);

        // Handle JSONObject
        if (data instanceof JSONObject) {
            try {
                JSONObject jsonObject = (JSONObject) data;
                Iterator<String> keys = jsonObject.keys();
                while (keys.hasNext()) {
                    String key = keys.next();
                    Object value = jsonObject.get(key);
                    if (value != null) {
                        analyzeRecursive(value, result, typeCounts, currentDepth + 1);
                    }
                }
            } catch (JSONException e) {
                logger.warning("Error accessing JSONObject elements: " + e.getMessage());
            }
        }
        // Handle JSONArray
        else if (data instanceof JSONArray) {
            try {
                JSONArray jsonArray = (JSONArray) data;
                for (int i = 0; i < jsonArray.length(); i++) {
                    Object element = jsonArray.get(i);
                    if (element != null) {
                        analyzeRecursive(element, result, typeCounts, currentDepth + 1);
                    }
                }
            } catch (JSONException e) {
                logger.warning("Error accessing JSONArray elements: " + e.getMessage());
            }
        }
        // Handle arrays (examining elements only if not byte[])
        else if (data.getClass().isArray() && !(data instanceof byte[])) {
            int length = Array.getLength(data);
            for (int i = 0; i < length; i++) {
                Object element = Array.get(data, i);
                if (element != null) {
                    analyzeRecursive(element, result, typeCounts, currentDepth + 1);
                }
            }
        }
        // Handle collections
        else if (data instanceof Collection) {
            Collection<?> collection = (Collection<?>) data;
            for (Object element : collection) {
                if (element != null) {
                    analyzeRecursive(element, result, typeCounts, currentDepth + 1);
                }
            }
        }
        // Handle maps
        else if (data instanceof Map) {
            Map<?, ?> map = (Map<?, ?>) data;
            for (Map.Entry<?, ?> entry : map.entrySet()) {
                if (entry.getKey() != null) {
                    analyzeRecursive(entry.getKey(), result, typeCounts, currentDepth + 1);
                }
                if (entry.getValue() != null) {
                    analyzeRecursive(entry.getValue(), result, typeCounts, currentDepth + 1);
                }
            }
        }
    }
}
