        if (totalItems < 0) {
            throw new IllegalArgumentException("Total items cannot be negative");
        }
        if (itemsPerPage <= 0) {
            throw new IllegalArgumentException("Items per page must be positive");
        }
        if (totalItems == 0) {
            return 0;
        }
        return (int) Math.ceil((double) totalItems / itemsPerPage);
    }
