import java.util.Collections;

class CargoOptimizer {

    public static int calculateMaxTrips(ArrayList<Integer> weights, int capacity) {
        int singleTrips = 0;
        ArrayList<Integer> remaining = new ArrayList<>();

        // First, count and remove items that can travel alone
        for (int weight : weights) {
            if (weight >= capacity) {
                singleTrips++;
            } else {
                remaining.add(weight);
            }
        }

        // Sort remaining items in descending order
        Collections.sort(remaining, Collections.reverseOrder());

        int left = 0;
        int right = remaining.size() - 1;
        int groupTrips = 0;

        while (left <= right) {
            int currentMax = remaining.get(left);
            int minGroupSize = (int) Math.ceil((double) capacity / currentMax);

            if (right - left + 1 >= minGroupSize) {
                groupTrips++;
                left++;
                right -= (minGroupSize - 1);
            } else {
                break;
            }
        }

        return singleTrips + groupTrips;
    }
}

