import java.util.Map;
import java.util.HashMap;
import java.util.stream.Collectors;
import java.util.regex.Pattern;
import java.util.regex.Matcher;

class DataProcessor {

    public static Map<String, Object> processEcommerceData(String categoriesJson, String cartJson) {
        List<String> categoryNames = new ArrayList<>();
        List<Integer> categoryNameLengths = new ArrayList<>();
        List<Integer> quantities = new ArrayList<>();

        // Extract category names using regex
        Pattern categoryPattern = Pattern.compile("\"name\":\"([^\"]*)\"");
        Matcher categoryMatcher = categoryPattern.matcher(categoriesJson);
        while (categoryMatcher.find()) {
            String name = categoryMatcher.group(1);
            categoryNames.add(name);
            categoryNameLengths.add(name.length());
        }

        // Extract quantities using regex
        Pattern quantityPattern = Pattern.compile("\"quantity\":\\s*(\\d+)");
        Matcher quantityMatcher = quantityPattern.matcher(cartJson);
        while (quantityMatcher.find()) {
            quantities.add(Integer.parseInt(quantityMatcher.group(1)));
        }

        // Calculate required values
        int totalCartItems = quantities.stream().mapToInt(Integer::intValue).sum();
        boolean hasEmptyCategories = categoryNames.stream().anyMatch(String::isEmpty);

        // Build result map
        Map<String, Object> result = new HashMap<>();
        result.put("categoryCount", categoryNames.size());
        result.put("totalCartItems", totalCartItems);
        result.put("categoryNames", categoryNames);
        result.put("hasEmptyCategories", hasEmptyCategories);
        result.put("categoryNameLengths", categoryNameLengths);

        return result;
    }
}

