    private double outerCutoff = -1;
    private double falloffExponent = 1.0;

    public EnhancedSpotLight() {}

    public EnhancedSpotLight(Vector3 position, Vector3 direction, double cutoffAngle) {
        super(position);
        setDirection(direction);
        setCutoffAngle(cutoffAngle);
    }

    public EnhancedSpotLight(Vector3 position, Vector3 direction, double cutoffAngle, double outerCutoff, double falloffExponent) {
        super(position);
        setDirection(direction);
        setCutoffAngle(cutoffAngle);
        setOuterCutoff(outerCutoff);
        setFalloffExponent(falloffExponent);
    }

    @Override
    public void setPosition(Vector3 position) {
        if (position == null) {
            throw new IllegalArgumentException("Position cannot be null");
        }
        super.setPosition(position);
    }

    public Vector3 getDirection() { return direction; }
    public void setDirection(Vector3 direction) {
        if (direction == null) {
            throw new IllegalArgumentException("Direction cannot be null");
        }
        this.direction = direction;
    }

    public double getCutoffAngle() { return cutoffAngle; }
    public void setCutoffAngle(double cutoffAngle) {
        if (cutoffAngle < 0 || cutoffAngle > 90) {
            throw new IllegalArgumentException("Cutoff angle must be between 0 and 90 degrees");
        }
        if (this.outerCutoff >= 0 && this.outerCutoff <= 90 && cutoffAngle >= this.outerCutoff) {
            throw new IllegalArgumentException("Cutoff must be less than outer cutoff");
        }
        this.cutoffAngle = cutoffAngle;
    }

    public double getOuterCutoff() { return outerCutoff; }
    public void setOuterCutoff(double outerCutoff) {
        if (outerCutoff < 0 || outerCutoff > 90) {
            throw new IllegalArgumentException("Outer cutoff must be between 0 and 90 degrees");
        }
        if (outerCutoff <= this.cutoffAngle) {
            throw new IllegalArgumentException("Outer cutoff must be greater than cutoff");
        }
        this.outerCutoff = outerCutoff;
    }

    public double getFalloffExponent() { return falloffExponent; }
    public void setFalloffExponent(double falloffExponent) {
        if (falloffExponent <= 0) {
            throw new IllegalArgumentException("Falloff exponent must be positive");
        }
        this.falloffExponent = falloffExponent;
    }

    public double calculateIntensity(Vector3 point) {
        if (outerCutoff < 0) {
            // If outer cutoff is not set, use simple cutoff without smooth transition
            Vector3 toPoint = point.sub(getPosition()).normalized();
            double cosTheta = toPoint.dot(direction.normalized());
            double cosCutoff = Math.cos(Math.toRadians(cutoffAngle));
