            } else if (cosTheta > cosInnerCutoff) {
                return 1.0; // Inside the inner cone
            } else {
                // In the transition region between inner and outer cutoff
                double attenuation = (cosTheta - cosOuterCutoff) / (cosInnerCutoff - cosOuterCutoff);
                return Math.pow(attenuation, falloffExponent);
            }
        }
