import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.List;
import java.util.ArrayList;

class State {
    private String name;
    private boolean isAccepting;
    private Map<Character, State> transitions;

    public State(String name, boolean isAccepting) {
        this.name = name;
        this.isAccepting = isAccepting;
        this.transitions = new HashMap<>();
    }

    public String getName() {
        return name;
    }

    public boolean isAccepting() {
        return isAccepting;
    }

    public void addTransition(char symbol, State nextState) {
        transitions.put(symbol, nextState);
    }

    public State getNextState(char symbol) {
        return transitions.get(symbol);
    }

    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder();
        sb.append(name).append(": ");
        boolean first = true;
        for (Map.Entry<Character, State> entry : transitions.entrySet()) {
            if (!first) {
                sb.append(" ");
            }
            sb.append("--").append(entry.getKey()).append("-> ").append(entry.getValue().getName());
            first = false;
        }
        return sb.toString();
    }
}

class DFA {
    private State initialState;
    private List<State> states;
    private Set<Character> alphabet;

    public DFA() {
        states = new ArrayList<>();
        alphabet = new HashSet<>();
    }

    public void addState(State state) {
        if (states.isEmpty()) {
            initialState = state;
        }
        states.add(state);
    }

    public void addTransition(State fromState, char symbol, State toState) {
        fromState.addTransition(symbol, toState);
        alphabet.add(symbol);
    }

    public Set<Character> getAlphabet() {
        return new HashSet<>(alphabet);
    }

    public boolean accepts(String input) {
        State currentState = initialState;
        for (int i = 0; i < input.length(); i++) {
            char c = input.charAt(i);
            State nextState = currentState.getNextState(c);
            if (nextState == null) {
                return false;
            }
            currentState = nextState;
        }
        return currentState.isAccepting();
    }

    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder();
        sb.append("DFA with ").append(states.size()).append(" states\n");
        sb.append("Alphabet: ").append(alphabet).append("\n");
        sb.append("Initial state: ").append(initialState.getName()).append("\n");

        List<String> finalStates = new ArrayList<>();
        for (State state : states) {
            if (state.isAccepting()) {
                finalStates.add(state.getName());
            }
        }
        sb.append("Final states: ").append(finalStates).append("\n");

        sb.append("Transitions:\n");
        for (State state : states) {
            sb.append(state.toString()).append("\n");
        }

        return sb.toString();
    }
}

