import java.util.function.Consumer;
import java.util.function.Predicate;

public class EnhancedTestUtils {

    public static <T, E extends Throwable> Consumer<T> enhancedExceptionExpectation(Class<E> expectedExceptionClass,
                                                                                    Predicate<E> validator,
                                                                                    Consumer<T> operation) {
        if (expectedExceptionClass == null) {
            throw new NullPointerException("Expected exception class must not be null");
        }
        if (operation == null) {
            throw new NullPointerException("Operation must not be null");
        }

        return input -> {
            try {
                operation.accept(input);
                throw new AssertionError("Expected exception of type " + expectedExceptionClass.getSimpleName() + 
                                       " but no exception was thrown.");
            } catch (Throwable actualException) {
                if (!expectedExceptionClass.isInstance(actualException)) {
                    throw new AssertionError("Expected exception of type " + expectedExceptionClass.getSimpleName() + 
                                           " but got " + actualException.getClass().getSimpleName() + " instead.");
                }

                if (validator != null && !validator.test(expectedExceptionClass.cast(actualException))) {
                    throw new AssertionError("Thrown exception of type " + actualException.getClass().getSimpleName() + 
                                           " failed validation.");
                }
            }
        };
    }
}

