        if (extensionData == null) {
            result.put("status", Map.of("error", "Extension data cannot be null"));
            return result;
        }

        Map<String, Object> status;
        if ("EARLY_DATA".equals(extensionType)) {
            status = processEarlyDataExtension(extensionData);
        } else if ("SERVER_NAME".equals(extensionType)) {
            status = processServerNameExtension(extensionData);
        } else {
            status = Map.of("warning", "Unsupported extension type");
        }

        result.put("status", status);

        // Only update context if processing was successful
        if (!status.containsKey("error")) {
            updateTlsContext(extensionType, extensionData, context);
        }

        result.put("updatedContext", context);
        return result;
    }

    private Map<String, Object> processEarlyDataExtension(Map<String, Object> extensionData) {
        // Validate maxEarlyDataSize
        if (extensionData.containsKey("maxEarlyDataSize")) {
            Object maxEarlyDataSizeObj = extensionData.get("maxEarlyDataSize");
            if (!(maxEarlyDataSizeObj instanceof Integer)) {
                return Map.of("error", "maxEarlyDataSize must be a non-negative integer");
            }
            int maxEarlyDataSize = (Integer) maxEarlyDataSizeObj;
            if (maxEarlyDataSize < 0) {
                return Map.of("error", "maxEarlyDataSize must be a non-negative integer");
            }
        }

        // Validate connectionEnd
        Object connectionEndObj = extensionData.getOrDefault("connectionEnd", "CLIENT");
        if (!(connectionEndObj instanceof String)) {
            return Map.of("error", "connectionEnd must be either CLIENT or SERVER");
        }
        String connectionEnd = (String) connectionEndObj;
        if (!"CLIENT".equals(connectionEnd) && !"SERVER".equals(connectionEnd)) {
            return Map.of("error", "connectionEnd must be either CLIENT or SERVER");
        }

        // All validations passed
        Map<String, Object> successData = new HashMap<>();
        successData.put("message", "Extension processed successfully");
        successData.put("maxEarlyDataSize", extensionData.getOrDefault("maxEarlyDataSize", 0));
        successData.put("connectionEnd", connectionEnd);
        return successData;
    }

    private Map<String, Object> processServerNameExtension(Map<String, Object> extensionData) {
        // Validate serverName
        if (!extensionData.containsKey("serverName")) {
            return Map.of("error", "Server name cannot be empty");
        }

        Object serverNameObj = extensionData.get("serverName");
        if (!(serverNameObj instanceof String) || ((String) serverNameObj).isEmpty()) {
            return Map.of("error", "Server name cannot be empty");
        }

        // All validations passed
        Map<String, Object> successData = new HashMap<>();
        successData.put("message", "Extension processed successfully");
        successData.put("serverName", serverNameObj);
        return successData;
    }

    private void updateTlsContext(String extensionType, Map<String, Object> extensionData, Map<String, Object> context) {
        // Store entire extension data under extensionType key
        context.put(extensionType, extensionData);

        // Additional logic for EARLY_DATA extension
        if ("EARLY_DATA".equals(extensionType)) {
            // Store maxEarlyDataSize directly in context if present
            if (extensionData.containsKey("maxEarlyDataSize")) {
                context.put("maxEarlyDataSize", extensionData.get("maxEarlyDataSize"));
            }

            // Check if connectionEnd is SERVER
            Object connectionEnd = extensionData.getOrDefault("connectionEnd", "CLIENT");
            if ("SERVER".equals(connectionEnd)) {
                // Initialize negotiatedExtensions list if not present
                if (!context.containsKey("negotiatedExtensions")) {
                    context.put("negotiatedExtensions", new ArrayList<String>());
                }

                // Add EARLY_DATA to negotiatedExtensions list
                @SuppressWarnings("unchecked")
                List<String> negotiatedExtensions = (List<String>) context.get("negotiatedExtensions");
                negotiatedExtensions.add("EARLY_DATA");
            }
        }
    }
}
