        result.put("count", nodeCount[0]);
        result.put("maxDiff", maxDiff[0]);
        result.put("minDiff", minDiff[0]);
        result.put("avgDiff", avgDiff);
        return result;
    }

    private void dfs(TreeNode node, Integer minAncestor, Integer maxAncestor, TreeSet<Integer> ancestors, int[] nodeCount, int[] totalSum, int[] minDiff, int[] maxDiff) {
        if (node == null) {
            return;
        }

        nodeCount[0]++;

        if (!ancestors.isEmpty()) {
            int diffWithMin = Math.abs(node.val - minAncestor);
            int diffWithMax = Math.abs(node.val - maxAncestor);
            int currentMaxDiff = Math.max(diffWithMin, diffWithMax);
            if (currentMaxDiff > maxDiff[0]) {
                maxDiff[0] = currentMaxDiff;
