import java.util.concurrent.TimeUnit;

public class ConfigurationManager {
    private Map<String, Object> configMap;
    private Set<String> requiredKeys;
    private Map<String, List<Validator>> validators;

    public ConfigurationManager(Set<String> requiredKeys, Map<String, List<Validator>> validators) {
        this.requiredKeys = requiredKeys != null ? new HashSet<>(requiredKeys) : new HashSet<>();
        this.validators = new HashMap<>();
        if (validators != null) {
            for (Map.Entry<String, List<Validator>> entry : validators.entrySet()) {
                this.validators.put(entry.getKey(), new ArrayList<>(entry.getValue()));
            }
        }
        this.configMap = new HashMap<>();
    }

    public void loadConfiguration(Map<String, Object> properties) {
        Set<String> missingKeys = new HashSet<>();
        for (String key : requiredKeys) {
            if (!properties.containsKey(key)) {
                missingKeys.add(key);
            }
        }
        if (!missingKeys.isEmpty()) {
            throw new ConfigurationException("Missing required configuration keys: " + missingKeys);
        }
        configMap.putAll(properties);
        validateConfiguration();
    }

    private void validateConfiguration() {
        for (Map.Entry<String, List<Validator>> entry : validators.entrySet()) {
            String key = entry.getKey();
            if (configMap.containsKey(key)) {
                Object value = configMap.get(key);
                for (Validator validator : entry.getValue()) {
                    validator.validate(value);
                }
            }
        }
    }

    public <T> T getConfigValue(String key, Class<T> type) {
        Object value = configMap.get(key);
        if (value == null) {
            throw new ConfigurationException("Configuration key '" + key + "' not found");
        }

        // If the value is already of the requested type, return it directly
        if (type.isInstance(value)) {
            return type.cast(value);
        }

        // Convert the value to string for parsing
        String stringValue = String.valueOf(value);

        try {
            if (type == Integer.class || type == int.class) {
                return type.cast(Integer.parseInt(stringValue));
            } else if (type == Long.class || type == long.class) {
                return type.cast(Long.parseLong(stringValue));
            } else if (type == Double.class || type == double.class) {
                return type.cast(Double.parseDouble(stringValue));
            } else if (type == Boolean.class || type == boolean.class) {
