    public static class UserInfo {
        private String phoneNumber;
        private String name;

        public UserInfo(String phoneNumber, String name) {
            this.phoneNumber = phoneNumber;
            this.name = name;
        }

        public String getPhoneNumber() { return phoneNumber; }
        public String getName() { return name; }

        @Override
        public String toString() {
            return "UserInfo{phoneNumber='" + phoneNumber + "', name='" + name + "'}";
        }
    }

    public Map<String, Object> processContacts(List<PhoneContact> phoneContacts) {
        List<UserInfo> processedUsers = new ArrayList<>();
        int batchSize = 200;
        int batchesProcessed = 0;
        int duplicateCount = 0;
        Set<String> seenPhoneNumbers = new HashSet<>();

        for (int i = 0; i < phoneContacts.size(); i += batchSize) {
            List<PhoneContact> batch = phoneContacts.subList(
                i, Math.min(i + batchSize, phoneContacts.size()));

            for (PhoneContact contact : batch) {
                String phoneNumber = contact.getPhoneNumber();
                if (phoneNumber == null || phoneNumber.trim().isEmpty()) {
                    continue;
