                if (seenPhoneNumbers.contains(phoneNumber)) {
                    duplicateCount++;
                } else {
                    seenPhoneNumbers.add(phoneNumber);
                    processedUsers.add(new UserInfo(phoneNumber, contact.getName()));
                }
            }

            batchesProcessed++;
        }

        Map<String, Object> result = new HashMap<>();
        result.put("users", processedUsers);
        result.put("batchesProcessed", batchesProcessed);
        result.put("duplicateContacts", duplicateCount);
        return result;
    }
}

