class NeuralNetworkCalculator {
    private final int inputSize;
    private final int hiddenSize;
    private final int outputSize;
    private final double[] weights;
    private final double[][] inputNormalizationParams;
    private final double[][] outputNormalizationParams;

    public NeuralNetworkCalculator(int inputSize, int hiddenSize, int outputSize, 
                                 double[] weights, double[][] inputNormParams, 
                                 double[][] outputNormParams) {
        this.inputSize = inputSize;
        this.hiddenSize = hiddenSize;
        this.outputSize = outputSize;
        this.weights = weights;
        this.inputNormalizationParams = inputNormParams;
        this.outputNormalizationParams = outputNormParams;
    }

    public double[] calculate(double[] input) {
        if (input.length != inputSize) {
            throw new IllegalArgumentException("Input size mismatch");
        }

        // Normalize input
        double[] normalizedInput = new double[inputSize];
        for (int i = 0; i < inputSize; i++) {
            double mean = inputNormalizationParams[i][0];
            double std = inputNormalizationParams[i][1];
            normalizedInput[i] = (input[i] - mean) / std;
        }

        // Prepare input layer with bias
        double[] inputWithBias = new double[inputSize + 1];
        System.arraycopy(normalizedInput, 0, inputWithBias, 0, inputSize);
        inputWithBias[inputSize] = 1.0;  // Bias term

        // Calculate hidden layer with ReLU activation
        double[] hiddenPre = new double[hiddenSize];
        int weightIndex = 0;

        // Input to hidden layer weights
        for (int h = 0; h < hiddenSize; h++) {
            double sum = 0;
            for (int i = 0; i <= inputSize; i++) {  // Include bias
                sum += inputWithBias[i] * weights[weightIndex++];
            }
            hiddenPre[h] = Math.max(0, sum);  // ReLU activation
        }

        // Prepare hidden layer with bias
        double[] hiddenWithBias = new double[hiddenSize + 1];
        System.arraycopy(hiddenPre, 0, hiddenWithBias, 0, hiddenSize);
        hiddenWithBias[hiddenSize] = 1.0;  // Bias term

        // Calculate output layer (linear activation)
        double[] normalizedOutput = new double[outputSize];
        for (int o = 0; o < outputSize; o++) {
            double sum = 0;
            for (int h = 0; h <= hiddenSize; h++) {  // Include bias
                sum += hiddenWithBias[h] * weights[weightIndex++];
            }
            normalizedOutput[o] = sum;
        }

        // Denormalize output
        double[] output = new double[outputSize];
        for (int o = 0; o < outputSize; o++) {
            double mean = outputNormalizationParams[o][0];
            double std = outputNormalizationParams[o][1];
            output[o] = normalizedOutput[o] * std + mean;
        }

        return output;
    }
}

