import java.util.concurrent.ConcurrentHashMap;
import java.util.Map;
import java.util.Queue;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.ArrayList;
import java.util.List;
import java.util.Collections;
import java.util.Comparator;
import java.util.concurrent.CopyOnWriteArrayList;
import java.io.OutputStream;

class PlayerInfo {
    private final String playerId;
    private int score;
    private boolean active;

    public PlayerInfo(String playerId, int score) {
        this.playerId = playerId;
        this.score = score;
        this.active = true;
    }

    public String getPlayerId() { return playerId; }
    public int getScore() { return score; }
    public boolean isActive() { return active; }

    public void setScore(int score) { this.score = score; }
    public void setActive(boolean active) { this.active = active; }
}

class PlayerManagementSystem {
    private final Map<String, PlayerInfo> players = new ConcurrentHashMap<>();
    private final Queue<String> turnQueue = new ConcurrentLinkedQueue<>();
    private final List<OutputStream> outputStreams = new CopyOnWriteArrayList<>();

    public synchronized boolean registerPlayer(String playerId, int score) {
        if (players.containsKey(playerId)) {
            return false;
        }
        PlayerInfo newPlayer = new PlayerInfo(playerId, score);
        players.put(playerId, newPlayer);
        turnQueue.add(playerId);
        return true;
    }

    public synchronized boolean removePlayer(String playerId) {
        PlayerInfo player = players.get(playerId);
        if (player == null || !player.isActive()) {
            return false;
        }
        player.setActive(false);
        turnQueue.remove(playerId);
        return true;
    }

    public synchronized boolean updateScore(String playerId, int points) {
        PlayerInfo player = players.get(playerId);
        if (player == null || !player.isActive()) {
            return false;
        }
        player.setScore(player.getScore() + points);
        return true;
    }

    public synchronized PlayerInfo getNextPlayer() {
        if (turnQueue.isEmpty()) {
            return null;
        }

        String nextPlayerId = turnQueue.poll();
        PlayerInfo nextPlayer = players.get(nextPlayerId);

        // Check if player is still active and exists
        if (nextPlayer != null && nextPlayer.isActive()) {
            // Return player to the end of the queue
            turnQueue.add(nextPlayerId);
            return nextPlayer;
        } else {
            // If player is invalid, recursively try next player
            return getNextPlayer();
        }
    }

    public synchronized List<PlayerInfo> getRankings() {
        List<PlayerInfo> activePlayers = new ArrayList<>();
        for (PlayerInfo player : players.values()) {
            if (player.isActive()) {
                activePlayers.add(player);
            }
        }

        // Sort by score in descending order
        Collections.sort(activePlayers, new Comparator<PlayerInfo>() {
            @Override
            public int compare(PlayerInfo p1, PlayerInfo p2) {
                return Integer.compare(p2.getScore(), p1.getScore());
            }
        });

        return activePlayers;
    }

    public synchronized void addOutputStream(OutputStream stream) {
        outputStreams.add(stream);
    }

    public synchronized boolean removeOutputStream(OutputStream stream) {
        return outputStreams.remove(stream);
    }

    public synchronized List<OutputStream> getOutputStreams() {
        return new ArrayList<>(outputStreams);
    }
}

