import java.util.*;

class Tariff {
    private String id;
    private String name;
    private double monthlyFee;

    public Tariff(String id, String name, double monthlyFee) {
        this.id = id;
        this.name = name;
        this.monthlyFee = monthlyFee;
    }

    public String getId() {
        return id;
    }

    public String getName() {
        return name;
    }

    public double getMonthlyFee() {
        return monthlyFee;
    }
}

class Contract {
    private String id;
    private String clientName;

    public Contract(String id, String clientName) {
        this.id = id;
        this.clientName = clientName;
    }

    public String getId() {
        return id;
    }

    public String getClientName() {
        return clientName;
    }
}

class EnhancedTariffManager {
    private Map<String, Tariff> tariffs = new HashMap<>();
    private Map<String, List<Contract>> tariffContracts = new HashMap<>();

    public void addTariff(Tariff tariff) {
        if (tariffs.containsKey(tariff.getId())) {
            throw new IllegalArgumentException("Tariff ID already exists");
        }
        tariffs.put(tariff.getId(), tariff);
        tariffContracts.put(tariff.getId(), new ArrayList<>());
    }

    public void subscribeContract(String tariffId, Contract contract) {
        if (!tariffs.containsKey(tariffId)) {
            throw new IllegalArgumentException("Tariff does not exist");
        }

        // Check if contract ID is already subscribed to any tariff
        for (List<Contract> contracts : tariffContracts.values()) {
            for (Contract c : contracts) {
                if (c.getId().equals(contract.getId())) {
                    throw new IllegalArgumentException("Contract ID already subscribed");
                }
            }
        }

        tariffContracts.get(tariffId).add(contract);
    }

    public List<Contract> getContractsForTariff(String tariffId) {
        if (!tariffs.containsKey(tariffId)) {
            throw new IllegalArgumentException("Tariff does not exist");
        }
        return Collections.unmodifiableList(tariffContracts.get(tariffId));
    }

    public Tariff getTariff(String tariffId) {
        return tariffs.get(tariffId);
    }
}

