class CatResult {
    private List<CategoryNode> data;

    public CatResult(List<CategoryNode> data) {
        this.data = data;
    }

    public List<CategoryNode> getData() {
        return data;
    }

    public void setData(List<CategoryNode> data) {
        this.data = data;
    }
}

class ItemCatService {
    private Map<Long, Category> categories = new HashMap<>();
    private Map<Long, List<Category>> childrenMap = new HashMap<>();

    public void addCategory(Long id, String name, Long parentId) {
        Category category = new Category(id, name, parentId);
        categories.put(id, category);

        // Add to children map
        childrenMap.computeIfAbsent(parentId, k -> new ArrayList<>()).add(category);
    }

    public CatResult getItemCatList() {
        if (categories.isEmpty()) {
            return new CatResult(new ArrayList<>());
        }

        List<CategoryNode> rootNodes = new ArrayList<>();
        List<Category> rootCategories = childrenMap.get(0L);

        if (rootCategories != null) {
            for (Category rootCategory : rootCategories) {
                rootNodes.add(buildCategoryTree(rootCategory));
            }
        }

        return new CatResult(rootNodes);
    }

    private CategoryNode buildCategoryTree(Category category) {
        CategoryNode node = new CategoryNode();
        node.setData(category);

        List<Category> children = childrenMap.get(category.getId());
        if (children != null) {
            for (Category child : children) {
                node.getChildren().add(buildCategoryTree(child));
            }
        }

        return node;
    }
}

