public class Factory {
    private int version;
    private int[] inputStocks;

    public Factory(int version, int initialInput) {
        this.version = version;
        this.inputStocks = new int[version];
        this.inputStocks[0] = initialInput;
    }

    public int[] process(int n) {
        int flow = n;
        int processedThisRun = 0;
        for (int i = 0; i < version; i++) {
            int processedInWorkshop = Math.min(flow, inputStocks[i]);
            inputStocks[i] -= processedInWorkshop;
            if (i == version - 1) {
                processedThisRun = processedInWorkshop;
            } else {
                inputStocks[i + 1] += processedInWorkshop;
            }
            flow = processedInWorkshop;
        }
        return new int[]{processedThisRun, inputStocks[0]};
    }
}

