import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.locks.ReentrantLock;

public class Factory {
    private final int version;
    private final AtomicInteger[] workshopStocks;
    private final AtomicInteger outputStock = new AtomicInteger(0);
    private final Thread[] workshopThreads;
    private volatile boolean isRunning = false;
    private final int totalItemsToProcess;
    private final AtomicInteger processedCount = new AtomicInteger(0);
    private final AtomicInteger errorCount = new AtomicInteger(0);
    private final ReentrantLock[] stockLocks;
    private long startTime;
    private long endTime;

    public Factory(int version, int initialInput, int itemsToProcess) {
        this.version = version;
        this.totalItemsToProcess = itemsToProcess;
        this.workshopStocks = new AtomicInteger[version];
        this.stockLocks = new ReentrantLock[version + 1]; // +1 for output stock

        for (int i = 0; i < version; i++) {
            workshopStocks[i] = new AtomicInteger(i == 0 ? initialInput : 0);
            stockLocks[i] = new ReentrantLock();
        }
        stockLocks[version] = new ReentrantLock(); // Lock for output stock

        this.workshopThreads = new Thread[version];
        initializeWorkshops();
    }

    private void initializeWorkshops() {
        for (int i = 0; i < version; i++) {
            final int workshopIndex = i;
            workshopThreads[i] = new Thread(() -> {
                while (isRunning && processedCount.get() < totalItemsToProcess) {
                    try {
                        processItem(workshopIndex);
                        Thread.sleep(10); // Simulate processing time
                    } catch (Exception e) {
                        errorCount.incrementAndGet();
                    }
                }
            });
        }
    }

    private void processItem(int workshopIndex) {
        // Acquire locks in a consistent order to prevent deadlocks
        int nextStockIndex = workshopIndex == version - 1 ? version : workshopIndex + 1;

        // Try to acquire locks with timeout to prevent deadlocks
        try {
            if (stockLocks[workshopIndex].tryLock() && stockLocks[nextStockIndex].tryLock()) {
                try {
                    int availableItems = workshopStocks[workshopIndex].get();
                    if (availableItems <= 0 || processedCount.get() >= totalItemsToProcess) return;

                    // Process one item
                    workshopStocks[workshopIndex].decrementAndGet();

                    if (workshopIndex == version - 1) {
                        outputStock.incrementAndGet();
                        processedCount.incrementAndGet();
                    } else {
                        workshopStocks[workshopIndex + 1].incrementAndGet();
                    }
                } finally {
                    stockLocks[nextStockIndex].unlock();
                    stockLocks[workshopIndex].unlock();
                }
            }
        } catch (Exception e) {
            errorCount.incrementAndGet();
        }
    }

    public PerformanceStats processItems() {
        startTime = System.currentTimeMillis();
        isRunning = true;

        for (Thread workshopThread : workshopThreads) {
            workshopThread.start();
        }

        // Wait for processing to complete
        while (processedCount.get() < totalItemsToProcess && 
               getTotalItemsInPipeline() > 0) {
            try {
                Thread.sleep(100);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                break;
            }
        }

        isRunning = false;
        for (Thread workshopThread : workshopThreads) {
            try {
                workshopThread.join(1000);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }

        endTime = System.currentTimeMillis();

        return getPerformanceStats();
    }

    private int getTotalItemsInPipeline() {
        int total = 0;
        for (int i = 0; i < version; i++) {
            total += workshopStocks[i].get();
        }
        total += outputStock.get();
        return total;
    }

    public PerformanceStats getPerformanceStats() {
        int[] intermediateStocks = new int[version - 1];
        for (int i = 1; i < version; i++) {
            intermediateStocks[i - 1] = workshopStocks[i].get();
        }

        return new PerformanceStats(
            endTime - startTime,
            processedCount.get(),
            errorCount.get(),
            workshopStocks[0].get(), // Input stock
            intermediateStocks,
            outputStock.get()
        );
    }

    public static class PerformanceStats {
        public final long totalTimeMs;
        public final int processedItems;
        public final int errorCount;
        public final int inputStock;
        public final int[] intermediateStocks;
        public final int outputStock;

        public PerformanceStats(long totalTimeMs, int processedItems, int errorCount, 
                               int inputStock, int[] intermediateStocks, int outputStock) {
            this.totalTimeMs = totalTimeMs;
            this.processedItems = processedItems;
            this.errorCount = errorCount;
            this.inputStock = inputStock;
            this.intermediateStocks = intermediateStocks;
            this.outputStock = outputStock;
        }

        @Override
        public String toString() {
            StringBuilder sb = new StringBuilder();
            sb.append("Performance Statistics:\n");
            sb.append("Total Execution Time: ").append(totalTimeMs).append(" ms\n");
            sb.append("Processed Items: ").append(processedItems).append("\n");
            sb.append("Errors: ").append(errorCount).append("\n");
            sb.append("Input Stock: ").append(inputStock).append("\n");

            for (int i = 0; i < intermediateStocks.length; i++) {
                sb.append("Intermediate Stock ").append(i + 1).append(": ").append(intermediateStocks[i]).append("\n");
            }

            sb.append("Output Stock: ").append(outputStock).append("\n");
            return sb.toString();
        }
    }
}

